# PrüfTurbo GUI icon support.
# The .ico is embedded so the window icon works even when this script is moved.
PRUEFTURBO_ICON_FILENAME = "PruefTurbo_Icon.ico"
PRUEFTURBO_ICON_BASE64 = """"""


def get_pruefturbo_icon_path() -> Path:
    """Return a usable PrüfTurbo .ico path, extracting the embedded icon if needed."""
    candidate_dirs = []
    try:
        if getattr(sys, "frozen", False):
            candidate_dirs.append(Path(sys.executable).resolve().parent)
            if hasattr(sys, "_MEIPASS"):
                candidate_dirs.append(Path(sys._MEIPASS))
        candidate_dirs.append(Path(__file__).resolve().parent)
    except Exception:
        pass
    candidate_dirs.append(Path.cwd())

    for folder in candidate_dirs:
        try:
            candidate = folder / PRUEFTURBO_ICON_FILENAME
            if candidate.exists():
                return candidate
        except Exception:
            pass

    try:
        target_dir = _pruefturbo_app_dir() if "_pruefturbo_app_dir" in globals() else Path.cwd()
        target = target_dir / PRUEFTURBO_ICON_FILENAME
        if not target.exists():
            target.write_bytes(base64.b64decode(PRUEFTURBO_ICON_BASE64))
        return target
    except Exception:
        return Path(PRUEFTURBO_ICON_FILENAME)


def apply_pruefturbo_window_icon(window) -> None:
    """Apply the PrüfTurbo icon to a Tk or Toplevel window."""
    try:
        icon_file = str(get_pruefturbo_icon_path())
        window.iconbitmap(default=icon_file)
        window.iconbitmap(icon_file)
    except Exception:
        pass

