def safe_filename(text: str, fallback: str = "testcase") -> str:
    """Create a Windows/Linux-safe file name from a Test Case ID."""
    name = re.sub(r"[<>:\"/\\|?*]+", "_", clean_text(text))
    name = re.sub(r"\s+", "_", name).strip("._ ")
    if not name:
        name = fallback
    # This is an existing comment written by the developer to explain the code.
    # Avoid very long paths and reserved-looking empty names.
    return name[:120]


