def strip_leading_step_number(line: str) -> str:
    """
    Remove leading test-step numbering before dictionary grouping.

    Examples:
    1- Fault free  -> Fault free
    2. Fault free  -> Fault free
    3) Fault free  -> Fault free

    The original numbered text is still kept in examples/export.
    """
    # Normalize input to string.
    text_value = str(line or "").strip()
    # Remove common leading numbering styles: 1-, 1., 1), 1 -, 1 .
    text_value = re.sub(r"^\s*\d+\s*[-.)]\s*", "", text_value)
    # Return the cleaned text.
    return text_value.strip()


def normalize_dictionary_pattern(line: str):
    """
    Convert similar test-step lines into reusable dictionary patterns with [P1], [P2]...
    The same parameterized expression is used for both Dictionary Entry and Translation.

    Example:
    ECU responds with positive response (0x62 F404): 62 F4 04 XX
    -> ECU responds with positive response [P1]: [P2]
    """
    # Remove leading step number before dictionary grouping.
    line_without_step_number = strip_leading_step_number(line)

    # Normalize spaces so similar lines can be grouped reliably.
    original = " ".join(str(line_without_step_number or "").strip().split())
    if not original:
        return "", "", []

    # Normalize colon spacing.
    working = re.sub(r"\s*:\s*", ": ", original)
    working = re.sub(r"\s+", " ", working).strip()

    # General response pattern with parenthesized parameter and payload parameter.
    # Example:
    # ECU responds with positive response (0x62 F404): 62 F4 04 XX
    # -> ECU responds with positive response [P1]: [P2]
    m = re.match(
        r"^(.*?\bresponse)\s*\(([^)]+)\)\s*:\s*(.+)$",
        working,
        flags=re.IGNORECASE,
    )
    if m:
        prefix = m.group(1).strip()
        p1 = m.group(2).strip()
        p2 = m.group(3).strip()
        dictionary_entry = f"{prefix} [P1]: [P2]"
        return dictionary_entry, dictionary_entry, [p1, p2]

    # Generic pattern for any text with a parenthesized parameter followed by colon payload.
    # This applies to all entries, not only ECU response lines.
    m = re.match(
        r"^(.*?)\s*\(([^)]+)\)\s*:\s*(.+)$",
        working,
        flags=re.IGNORECASE,
    )
    if m:
        prefix = m.group(1).strip()
        p1 = m.group(2).strip()
        p2 = m.group(3).strip()
        dictionary_entry = f"{prefix} [P1]: [P2]"
        return dictionary_entry, dictionary_entry, [p1, p2]

    # Specific UDS request pattern.
    # Example:
    # Send Service $22 request to read DID 0xF404: 22 F4 04
    # -> Send Service [P1] request to [P2]: [P3]
    m = re.match(
        r"^(\d+\s*[-.)]\s*)?Send\s+Service\s+(\$?[0-9A-Fa-f]{2}|0x[0-9A-Fa-f]{2})\s+request\s+to\s+(.+?):\s*(.+)$",
        working,
        flags=re.IGNORECASE,
    )
    if m:
        prefix = m.group(1) or ""
        service = m.group(2).strip()
        action_target = m.group(3).strip()
        payload = m.group(4).strip()
        dictionary_entry = f"{prefix}Send Service [P1] request to [P2]: [P3]"
        return dictionary_entry, dictionary_entry, [service, action_target, payload]

    # Generic byte payload after colon.
    # Example:
    # Some step: 22 F4 04
    # -> Some step: [P1]
    m = re.match(r"^(.*?:)\s*((?:0x)?[0-9A-Fa-fXx]{2}(?:\s+(?:(?:0x)?[0-9A-Fa-fXx]{2}|XX|xx))+)$", working)
    if m:
        dictionary_entry = f"{m.group(1).strip()} [P1]"
        return dictionary_entry, dictionary_entry, [" ".join(m.group(2).strip().split())]

    # Generic DID abstraction.
    # Example:
    # read DID 0xF404 -> read DID [P1]
    m = re.search(r"\bDID\s+(0x[0-9A-Fa-f]+)\b", working, flags=re.IGNORECASE)
    if m:
        did = m.group(1)
        dictionary_entry = working.replace(did, "[P1]", 1)
        return dictionary_entry, dictionary_entry, [did]

    # Generic fallback for all remaining entries:
    # replace parenthesized hex values, colon payloads, and standalone hex IDs.
    params = []

    def add_param(value: str) -> str:
        params.append(value)
        return f"[P{len(params)}]"

    def replace_parenthesized(match):
        inner = match.group(1).strip()
        if re.search(r"(?:0x|\$)?[0-9A-Fa-f]{2,}|XX|xx", inner):
            return add_param(inner)
        return match.group(0)

    pattern_text = re.sub(r"\(([^)]*)\)", replace_parenthesized, working)

    m = re.match(r"^(.*?:)\s*(.+)$", pattern_text)
    if m and re.search(r"\b(?:[0-9A-Fa-f]{2}|0x[0-9A-Fa-f]{2}|XX|xx)\b", m.group(2)):
        pattern_text = f"{m.group(1).strip()} {add_param(m.group(2).strip())}"

    def repl_hex(match):
        return add_param(match.group(0))

    pattern_text = re.sub(r"\b(?:0x[0-9A-Fa-f]+|\$[0-9A-Fa-f]+)\b", repl_hex, pattern_text)
    pattern_text = re.sub(r"\s*:\s*", ": ", pattern_text)
    pattern_text = re.sub(r"\s+", " ", pattern_text).strip()

    if params:
        return pattern_text, pattern_text, params

    return working, working, []


class DictionaryOptimizerWindow(tk.Toplevel):
    """Editable Excel-like dictionary optimizer window."""

    def __init__(self, master, dictionary_rows):
        super().__init__(master)
        apply_pruefturbo_window_icon(self)
        self.title("Dictionary Optimization / Edit")
        self.geometry("1200x650")
        self.minsize(900, 500)
        # This stores a value in the current object so other methods can use it later.
        self.dictionary_rows = dictionary_rows
        # This stores a value in the current object so other methods can use it later.
        self.current_item = None

        top = ttk.Frame(self)
        top.pack(fill=tk.X, padx=8, pady=8)

        ttk.Label(
            top,
            text="Optimized dictionary entries. Edit a row by selecting it, changing the fields below, then click Update Selected."
        ).pack(side=tk.LEFT, fill=tk.X, expand=True)

        ttk.Button(top, text="Save Excel...", command=self.save_excel).pack(side=tk.RIGHT, padx=(8, 0))
        ttk.Button(top, text="Close", command=self.destroy).pack(side=tk.RIGHT)

        tree_frame = ttk.Frame(self)
        tree_frame.pack(fill=tk.BOTH, expand=True, padx=8, pady=(0, 8))

        self.tree = ttk.Treeview(
            tree_frame,
            columns=("entry", "translation", "count", "parameters", "examples"),
            show="headings",
            selectmode="browse"
        )
        self.tree.heading("entry", text="Dictionary Entry")
        self.tree.heading("translation", text="Translation")
        self.tree.heading("count", text="Count")
        self.tree.heading("parameters", text="Parameters")
        self.tree.heading("examples", text="Examples")

        self.tree.column("entry", width=360, stretch=True)
        self.tree.column("translation", width=360, stretch=True)
        self.tree.column("count", width=70, stretch=False, anchor=tk.CENTER)
        self.tree.column("parameters", width=220, stretch=True)
        self.tree.column("examples", width=360, stretch=True)

        self.tree.grid(row=0, column=0, sticky=tk.NSEW)
        yscroll = ttk.Scrollbar(tree_frame, orient=tk.VERTICAL, command=self.tree.yview)
        xscroll = ttk.Scrollbar(tree_frame, orient=tk.HORIZONTAL, command=self.tree.xview)
        self.tree.configure(yscrollcommand=yscroll.set, xscrollcommand=xscroll.set)
        yscroll.grid(row=0, column=1, sticky=tk.NS)
        xscroll.grid(row=1, column=0, sticky=tk.EW)
        tree_frame.rowconfigure(0, weight=1)
        tree_frame.columnconfigure(0, weight=1)

        editor = ttk.LabelFrame(self, text="Edit Selected Dictionary Row")
        editor.pack(fill=tk.X, padx=8, pady=(0, 8))
        editor.columnconfigure(1, weight=1)

        ttk.Label(editor, text="Dictionary Entry").grid(row=0, column=0, sticky=tk.W, padx=6, pady=4)
        # This stores a value in the current object so other methods can use it later.
        self.entry_var = tk.StringVar()
        ttk.Entry(editor, textvariable=self.entry_var).grid(row=0, column=1, sticky=tk.EW, padx=6, pady=4)

        ttk.Label(editor, text="Translation").grid(row=1, column=0, sticky=tk.W, padx=6, pady=4)
        # This stores a value in the current object so other methods can use it later.
        self.translation_var = tk.StringVar()
        ttk.Entry(editor, textvariable=self.translation_var).grid(row=1, column=1, sticky=tk.EW, padx=6, pady=4)

        ttk.Button(editor, text="Update Selected", command=self.update_selected).grid(row=0, column=2, rowspan=2, padx=6, pady=4)

        # This stores a value in the current object so other methods can use it later.
        self.status_var = tk.StringVar(value=f"Loaded {len(dictionary_rows)} optimized dictionary entries.")
        ttk.Label(self, textvariable=self.status_var, anchor=tk.W).pack(fill=tk.X, padx=8, pady=(0, 8))

        self.populate()
        self.tree.bind("<<TreeviewSelect>>", self.on_select)
        self.tree.bind("<Double-1>", self.on_double_click)

    def populate(self):
        for item in self.tree.get_children(""):
            self.tree.delete(item)

        for idx, row in enumerate(self.dictionary_rows):
            iid = str(idx)
            self.tree.insert(
                "",
                tk.END,
                iid=iid,
                values=(
                    row.get("entry", ""),
                    row.get("translation", ""),
                    row.get("count", 0),
                    "; ".join(row.get("parameter_examples", [])),
                    " | ".join(row.get("examples", [])[:3]),
                )
            )

    def on_select(self, event=None):
        selected = self.tree.selection()
        if not selected:
            return
        # This stores a value in the current object so other methods can use it later.
        self.current_item = selected[0]
        row = self.dictionary_rows[int(self.current_item)]
        self.entry_var.set(row.get("entry", ""))
        self.translation_var.set(row.get("translation", ""))

    def on_double_click(self, event=None):
        self.on_select(event)

    def update_selected(self):
        if self.current_item is None:
            messagebox.showinfo("Dictionary Optimizer", "Please select a dictionary row first.")
            return
        idx = int(self.current_item)
        self.dictionary_rows[idx]["entry"] = self.entry_var.get().strip()
        self.dictionary_rows[idx]["translation"] = self.translation_var.get().strip()
        self.populate()
        self.tree.selection_set(str(idx))
        self.status_var.set("Selected dictionary row updated.")

    def save_excel(self):
        try:
            from datetime import datetime
            from openpyxl import Workbook
            from openpyxl.styles import Alignment, Font
            from tkinter import filedialog

            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            target = filedialog.asksaveasfilename(
                title="Save optimized dictionary",
                defaultextension=".xlsx",
                initialfile=f"Optimized_Dict_{timestamp}.xlsx",
                filetypes=[("Excel workbook", "*.xlsx"), ("All files", "*.*")]
            )
            if not target:
                self.status_var.set("Save cancelled.")
                return

            # This creates a new Excel workbook in memory.
            wb = Workbook()
            ws = wb.active
            ws.title = "Optimized Dictionary"
            # This adds a new row of data into an Excel worksheet.
            ws.append([
                "Dictionary Entry",
                "Translation",
                "Occurrence Count",
                "Parameter Examples",
                "Original Examples",
                "Used In Test Case ID(s)",
                "Field(s)",
            ])

            for row in self.dictionary_rows:
                # This adds a new row of data into an Excel worksheet.
                ws.append([
                    row.get("entry", ""),
                    row.get("translation", ""),
                    row.get("count", 0),
                    "; ".join(row.get("parameter_examples", [])),
                    " | ".join(row.get("examples", [])),
                    "; ".join(sorted(row.get("testcases", []))),
                    "; ".join(sorted(row.get("fields", []))),
                ])

            # This freezes the header row in Excel so it stays visible while scrolling.
            ws.freeze_panes = "A2"
            # This enables Excel filter dropdowns for the used worksheet range.
            ws.auto_filter.ref = ws.dimensions
            for cell in ws[1]:
                # This changes the font style of an Excel cell.
                cell.font = Font(bold=True)
                # This formats how text is aligned inside an Excel cell.
                cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)

            for row_cells in ws.iter_rows(min_row=2):
                for cell in row_cells:
                    # This formats how text is aligned inside an Excel cell.
                    cell.alignment = Alignment(vertical="top", wrap_text=True)

            for col_cells in ws.columns:
                col_letter = col_cells[0].column_letter
                max_len = len(str(col_cells[0].value or ""))
                for cell in col_cells[1:]:
                    value = "" if cell.value is None else str(cell.value)
                    max_len = max(max_len, min(len(value), 90))
                ws.column_dimensions[col_letter].width = max(16, min(max_len + 2, 75))

            # This saves generated content to disk.
            wb.save(target)
            self.status_var.set(f"Saved optimized dictionary: {target}")
            messagebox.showinfo("Dictionary Optimizer", f"Saved successfully:\n{target}")

        except Exception as exc:
            self.status_var.set("Save failed.")
            messagebox.showerror("Save failed", f"Could not save optimized dictionary.\n\nDetails:\n{type(exc).__name__}: {exc}")




def _extract_cdd_name_near(text_value: str, start_index: int) -> str:
    # Select a small text window around the detected item.
    window = text_value[max(0, start_index - 500): start_index + 900]
    # Try to extract common name attributes used in XML-like CDD files.
    for pattern in [
        r'(?i)\bQUAL(?:IFIER)?\s*=\s*"([^"]+)"',
        r'(?i)\bNAME\s*=\s*"([^"]+)"',
        r'(?i)\bSHORT-NAME\s*>\s*([^<]+)\s*<',
        r'(?i)\bLONG-NAME\s*>\s*([^<]+)\s*<',
        r'(?i)\bCVALUETYPE\s*=\s*"([^"]+)"',
    ]:
        # Search for the pattern in the local window.
        match = re.search(pattern, window)
        # If a name was found, return it.
        if match:
            return match.group(1).strip()
    # Return dash when no name is found.
    return "-"


def _unique_cdd_items(items):
    # Create a set to remember unique rows.
    seen = set()
    # Create final output list.
    result = []
    # Loop over all parsed items.
    for item in items:
        # Create a uniqueness key based on item type, ID, and name.
        key = (item.get("type", ""), item.get("id", ""), item.get("name", ""))
        # Skip duplicates.
        if key in seen:
            continue
        # Remember this item.
        seen.add(key)
        # Add it to result.
        result.append(item)
    # Return unique items.
    return result



def _extract_xml_attribute(text_block: str, attribute_names):
    # Loop over possible attribute names.
    for attribute_name in attribute_names:
        # Search for attribute="value" format.
        match = re.search(r'(?i)\b' + re.escape(attribute_name) + r'\s*=\s*"([^"]+)"', text_block)
        # Return the first found attribute value.
        if match:
            return match.group(1).strip()
    # Return dash if no attribute was found.
    return "-"


def _extract_nearby_block(text_value: str, start_index: int, before: int = 400, after: int = 1200) -> str:
    # Return a text slice around a detected keyword so the parser can inspect nearby attributes.
    return text_value[max(0, start_index - before): start_index + after]


def parse_cdd_text(cdd_text: str):
    # Create list for parsed diagnostic objects.
    items = []

    # Extract UDS service IDs written as hex values after common service words.
    for match in re.finditer(r'(?i)\b(?:SERVICE|DIAG-SERVICE|SID|SERVICE-ID|REQUEST-SERVICE)\b[^0-9A-Fa-f]*(?:0x|\$)?([0-9A-Fa-f]{2})\b', cdd_text):
        # Build one parsed item.
        items.append({
            "type": "Diagnostic Service",
            "id": f"0x{match.group(1).upper()}",
            "name": _extract_cdd_name_near(cdd_text, match.start()),
            "source": "SERVICE/SID pattern",
        })

    # Extract DID identifiers from common DID naming patterns.
    for match in re.finditer(r'(?i)\b(?:DID|DATA-IDENTIFIER|IDENTIFIER|ID)\b[^0-9A-Fa-f]*(?:0x|\$)?([0-9A-Fa-f]{4})\b', cdd_text):
        # Build one parsed DID item.
        items.append({
            "type": "DID",
            "id": f"0x{match.group(1).upper()}",
            "name": _extract_cdd_name_near(cdd_text, match.start()),
            "source": "DID/DataIdentifier pattern",
        })

    # Extract routine identifiers.
    for match in re.finditer(r'(?i)\b(?:ROUTINE|RID|ROUTINE-ID|ROUTINEIDENTIFIER)\b[^0-9A-Fa-f]*(?:0x|\$)?([0-9A-Fa-f]{4})\b', cdd_text):
        # Build one parsed routine item.
        items.append({
            "type": "Routine ID",
            "id": f"0x{match.group(1).upper()}",
            "name": _extract_cdd_name_near(cdd_text, match.start()),
            "source": "Routine/RID pattern",
        })

    # Extract DTC-like identifiers.
    for match in re.finditer(r'(?i)\b(?:DTC|TROUBLE-CODE|FAULT-CODE)\b[^0-9A-Fa-f]*(?:0x|\$)?([0-9A-Fa-f]{6})\b', cdd_text):
        # Build one parsed DTC item.
        items.append({
            "type": "DTC",
            "id": f"0x{match.group(1).upper()}",
            "name": _extract_cdd_name_near(cdd_text, match.start()),
            "source": "DTC pattern",
        })

    # Fallback: extract XML attributes that directly contain hex values and classify by byte length.
    for match in re.finditer(r'(?i)\b(?:CVALU|VALUE|V|ID|CODE)\s*=\s*"(?:0x|\$)?([0-9A-Fa-f]{2,6})"', cdd_text):
        # Store the detected hex value.
        hex_value = match.group(1).upper()
        # Classify based on length.
        if len(hex_value) == 2:
            item_type = "Possible Service"
        elif len(hex_value) == 4:
            item_type = "Possible DID/RID"
        elif len(hex_value) == 6:
            item_type = "Possible DTC"
        else:
            item_type = "Possible Diagnostic ID"
        # Build fallback item.
        items.append({
            "type": item_type,
            "id": f"0x{hex_value}",
            "name": _extract_cdd_name_near(cdd_text, match.start()),
            "source": "Generic hex attribute",
        })

    # Extract CAN message definitions if they exist in the CDD/XML content.
    for match in re.finditer(r'(?i)\b(?:CAN-MESSAGE|CANMESSAGE|FRAME|CAN-FRAME|PDU|MESSAGE)\b', cdd_text):
        # Read surrounding text near the detected CAN message keyword.
        block = _extract_nearby_block(cdd_text, match.start())
        # Try to find a message name.
        message_name = _extract_xml_attribute(block, ["NAME", "QUAL", "QUALIFIER", "SHORT-NAME", "LONG-NAME"])
        # Try to find a CAN ID.
        can_id_match = re.search(r'(?i)\b(?:CAN-ID|CANID|FRAME-ID|IDENTIFIER|ID)\s*=\s*"(?:0x|\$)?([0-9A-Fa-f]{2,8})"', block)
        # Format CAN ID if found.
        can_id = f"0x{can_id_match.group(1).upper()}" if can_id_match else "-"
        # Try to find DLC if available.
        dlc_match = re.search(r'(?i)\b(?:DLC|LENGTH|BYTE-LENGTH)\s*=\s*"([^"]+)"', block)
        # Format DLC if found.
        dlc = dlc_match.group(1).strip() if dlc_match else "-"
        # Add CAN message item.
        items.append({
            "type": "CAN Message",
            "id": can_id,
            "name": message_name,
            "source": f"CAN message/frame pattern; DLC={dlc}",
        })

    # Extract CAN signal definitions if they exist in the CDD/XML content.
    for match in re.finditer(r'(?i)\b(?:CAN-SIGNAL|CANSIGNAL|SIGNAL|COMPU-METHOD|DATA-ELEMENT)\b', cdd_text):
        # Read surrounding text near the detected CAN signal keyword.
        block = _extract_nearby_block(cdd_text, match.start())
        # Try to find signal name.
        signal_name = _extract_xml_attribute(block, ["NAME", "QUAL", "QUALIFIER", "SHORT-NAME", "LONG-NAME"])
        # Try to find start bit.
        start_bit_match = re.search(r'(?i)\b(?:START-BIT|BIT-POSITION|BITPOSITION|STARTBIT)\s*=\s*"([^"]+)"', block)
        # Try to find bit length.
        length_match = re.search(r'(?i)\b(?:BIT-LENGTH|LENGTH|BITSIZE|BIT-SIZE)\s*=\s*"([^"]+)"', block)
        # Try to find parent message reference.
        message_ref_match = re.search(r'(?i)\b(?:MESSAGE|FRAME|PDU|PARENT|REF|MESSAGE-REF|FRAME-REF)\s*=\s*"([^"]+)"', block)
        # Format start bit.
        start_bit = start_bit_match.group(1).strip() if start_bit_match else "-"
        # Format bit length.
        bit_length = length_match.group(1).strip() if length_match else "-"
        # Format message reference.
        message_ref = message_ref_match.group(1).strip() if message_ref_match else "-"
        # Add CAN signal item.
        items.append({
            "type": "CAN Signal",
            "id": f"StartBit={start_bit}; Length={bit_length}",
            "name": signal_name,
            "source": f"CAN signal pattern; Message={message_ref}",
        })

    # Return unique parsed items.
    return _unique_cdd_items(items)



def optimize_specs_step_pattern(line: str):
    """
    Convert a concrete specs step into a standard dictionary-style command.

    Examples:
    Send request: [22 F4 30] -> Send request: [P1]
    Send [Service $22 request to read DID 0xF400]: [22 F4 00] -> Send [P1]: [P2]
    """
    # Keep original text safe.
    original = str(line or "").strip()
    # Remove leading step number so grouping does not depend on 1-, 2-, 3-.
    working = strip_leading_step_number(original)
    # Normalize repeated spaces.
    working = " ".join(working.split())
    # Stop for empty text.
    if not working:
        return "", []

    # Store extracted parameters in order.
    params = []

    # Replace every [ ... ] block with [P1], [P2], [P3]...
    def replace_square_parameter(match):
        params.append(match.group(1).strip())
        return f"[P{len(params)}]"

    # First handle square bracket parameters exactly as requested.
    optimized = re.sub(r"\[([^\]]+)\]", replace_square_parameter, working)

    # If square brackets existed, return immediately.
    if params:
        optimized = re.sub(r"\s*:\s*", ": ", optimized)
        optimized = re.sub(r"\s+", " ", optimized).strip()
        return optimized, params

    # Handle colon byte payload without brackets.
    # Example: Send request: 22 F4 30 -> Send request: [P1]
    m = re.match(r"^(.*?:)\s*((?:0x)?[0-9A-Fa-f]{2}(?:\s+(?:(?:0x)?[0-9A-Fa-f]{2}|XX|xx))+)$", working)
    if m:
        params.append(" ".join(m.group(2).split()))
        return f"{m.group(1).strip()} [P1]", params

    # Handle parenthesized value followed by payload.
    # Example: ECU responds with positive response (0x62 F404): 62 F4 04 XX -> ECU responds with positive response [P1]: [P2]
    m = re.match(r"^(.*?)\s*\(([^)]+)\)\s*:\s*(.+)$", working)
    if m:
        params.extend([m.group(2).strip(), m.group(3).strip()])
        return f"{m.group(1).strip()} [P1]: [P2]", params

    # No optimization possible.
    return working, []


def auto_add_square_brackets_for_specs_step(line: str):
    """
    Add square brackets around variable parts of a non-parameterized specs step.

    Goal:
    - Convert non-parameterized similar commands into a format that the optimizer can group.

    Examples:
    Send request: 22 F4 30
    -> Send request: [22 F4 30]

    Send Service $22 request to read DID 0xF400: 22 F4 00
    -> Send [Service $22 request to read DID 0xF400]: [22 F4 00]

    ECU responds with positive response (0x62 F404): 62 F4 04 XX
    -> ECU responds with positive response [0x62 F404]: [62 F4 04 XX]
    """
    # Keep original text safe.
    original = str(line or "").strip()

    # Remove step number only for detection.
    working = strip_leading_step_number(original)
    # Normalize spaces.
    working = " ".join(working.split())

    # Stop if text is empty.
    if not working:
        return working

    # If it already contains square brackets, keep it as-is.
    if "[" in working and "]" in working:
        return working

    # Pattern 1: "Send request: 22 F4 30" -> "Send request: [22 F4 30]"
    m = re.match(
        r"^(Send\s+request\s*:)\s*((?:0x)?[0-9A-Fa-f]{2}(?:\s+(?:(?:0x)?[0-9A-Fa-f]{2}|XX|xx))+)$",
        working,
        flags=re.IGNORECASE,
    )
    if m:
        return f"{m.group(1).strip()} [{m.group(2).strip()}]"

    # Pattern 2: "Send Service ...: 22 F4 00" -> "Send [Service ...]: [22 F4 00]"
    m = re.match(
        r"^(Send)\s+(.+?)\s*:\s*((?:0x)?[0-9A-Fa-f]{2}(?:\s+(?:(?:0x)?[0-9A-Fa-f]{2}|XX|xx))+)$",
        working,
        flags=re.IGNORECASE,
    )
    if m:
        return f"{m.group(1).strip()} [{m.group(2).strip()}]: [{m.group(3).strip()}]"

    # Pattern 3: "ECU responds ... (0x62 F404): 62 F4 04 XX" -> bracket both variable parts.
    m = re.match(
        r"^(.*?\bresponse)\s*\(([^)]+)\)\s*:\s*(.+)$",
        working,
        flags=re.IGNORECASE,
    )
    if m:
        return f"{m.group(1).strip()} [{m.group(2).strip()}]: [{m.group(3).strip()}]"

    # Pattern 4: any line ending with colon + byte payload -> bracket the payload.
    m = re.match(
        r"^(.*?:)\s*((?:0x)?[0-9A-Fa-f]{2}(?:\s+(?:(?:0x)?[0-9A-Fa-f]{2}|XX|xx))+)$",
        working,
        flags=re.IGNORECASE,
    )
    if m:
        return f"{m.group(1).strip()} [{m.group(2).strip()}]"

    # Pattern 5: generic "read DID 0xF400" inside text -> bracket DID value.
    working = re.sub(
        r"\b(DID\s+)(0x[0-9A-Fa-f]+)\b",
        lambda match: f"{match.group(1)}[{match.group(2)}]",
        working,
        flags=re.IGNORECASE,
    )

    # Return possibly modified text.
    return working


def tokenize_for_manual_grouping(line: str):
    # Remove step number and normalize spaces.
    clean = " ".join(strip_leading_step_number(line).split())
    # Split words, bracketed blocks, payload separators, and punctuation in a stable way.
    return re.findall(r"\[[^\]]+\]|0x[0-9A-Fa-f]+|\$[0-9A-Fa-f]+|[0-9A-Fa-f]{2}|XX|xx|[A-Za-z0-9_./+-]+|[:(),]", clean)


def build_manual_group_pattern(lines):
    """
    Build a manual grouping pattern by comparing selected lines token-by-token.

    Same tokens remain as fixed text.
    Different token regions become [P1], [P2], [P3]...
    """
    clean_lines = [" ".join(strip_leading_step_number(line).split()) for line in lines if str(line).strip()]
    if not clean_lines:
        return "", []
    token_lists = [tokenize_for_manual_grouping(line) for line in clean_lines]
    if len(token_lists) < 2:
        return clean_lines[0], []

    min_len = min(len(tokens) for tokens in token_lists)
    pattern_tokens = []
    params_per_line = [[] for _ in token_lists]
    param_index = 1
    i = 0

    while i < min_len:
        column_tokens = [tokens[i] for tokens in token_lists]
        if all(tok == column_tokens[0] for tok in column_tokens):
            pattern_tokens.append(column_tokens[0])
            i += 1
            continue

        start = i
        i += 1
        while i < min_len:
            next_column = [tokens[i] for tokens in token_lists]
            if all(tok == next_column[0] for tok in next_column):
                break
            i += 1

        pattern_tokens.append(f"[P{param_index}]")
        for row_idx, tokens in enumerate(token_lists):
            params_per_line[row_idx].append(" ".join(tokens[start:i]))
        param_index += 1

    if any(len(tokens) > min_len for tokens in token_lists):
        pattern_tokens.append(f"[P{param_index}]")
        for row_idx, tokens in enumerate(token_lists):
            params_per_line[row_idx].append(" ".join(tokens[min_len:]))

    pattern = " ".join(pattern_tokens)
    pattern = re.sub(r"\s+([:),])", r"\1", pattern)
    pattern = re.sub(r"([(])\s+", r"\1", pattern)
    pattern = re.sub(r"\s*:\s*", ": ", pattern)
    pattern = re.sub(r"\s+", " ", pattern).strip()

    return pattern, params_per_line


def split_step_cell_preserve_lines(value):
    # Convert value to safe string.
    raw = "" if value is None else str(value)
    # Normalize line breaks.
    raw = raw.replace("\r\n", "\n").replace("\r", "\n")
    # Return lines, preserving non-empty cleaned content only.
    return [line.strip() for line in raw.split("\n") if line.strip()]




def capl_dictionary_escape_comment(text_value: str) -> str:
    # Convert text to one safe CAPL comment line.
    return str(text_value or "").replace("\r", " ").replace("\n", " ").replace("*/", "* /").strip()


def capl_dictionary_escape_string(text_value: str) -> str:
    # Escape backslashes and double quotes for CAPL string literals.
    return str(text_value or "").replace("\\", "\\\\").replace('"', '\\"')


def clean_dictionary_command_text(command_text: str) -> str:
    # Normalize spaces around quotes and inside command text after parameter replacement.
    cleaned = str(command_text or "")
    # Remove duplicate spaces.
    cleaned = re.sub(r"[ \t]+", " ", cleaned)
    # Remove spaces directly after opening quote.
    cleaned = re.sub(r'"\s+', '"', cleaned)
    # Remove spaces directly before closing quote.
    cleaned = re.sub(r'\s+"', '"', cleaned)
    # Clean spaces around commas.
    cleaned = re.sub(r"\s*,\s*", ", ", cleaned)
    # Clean spaces before closing parenthesis.
    cleaned = re.sub(r"\s+\)", ")", cleaned)
    # Clean spaces after opening parenthesis.
    cleaned = re.sub(r"\(\s+", "(", cleaned)
    # Return final command.
    return cleaned.strip()


def dictionary_entry_to_regex(dictionary_entry: str):
    """Convert a dictionary entry with [P1], [P2] placeholders to a named-group regex.

    Named capture groups make parameter extraction deterministic and avoid fragile
    positional capture-index handling, especially for adjacent placeholders.
    Repeated placeholders receive internal unique group names and are normalized
    back to P1/P2/... by match_dictionary_entry().
    """
    template = str(dictionary_entry or "").strip()
    placeholder_pattern = re.compile(r"\[P(\d+)\]", flags=re.IGNORECASE)
    regex_parts = []
    placeholder_group_map = []
    pos = 0
    seen_counts: Dict[str, int] = {}

    for match in placeholder_pattern.finditer(template):
        regex_parts.append(re.escape(template[pos:match.start()]))
        placeholder_name = f"P{match.group(1)}".upper()
        seen_counts[placeholder_name] = seen_counts.get(placeholder_name, 0) + 1
        group_name = f"{placeholder_name}_{seen_counts[placeholder_name]}"
        placeholder_group_map.append((placeholder_name, group_name))

        # Accept either bracketed values ([Speed]) or plain values (Speed).
        regex_parts.append(fr"\s*(?:\[\s*(?P<{group_name}>.*?)\s*\]|(?P<{group_name}_free>.*?))\s*")
        pos = match.end()

    regex_parts.append(re.escape(template[pos:]))
    regex_text = r"^\s*" + "".join(regex_parts) + r"\s*$"
    return re.compile(regex_text, flags=re.IGNORECASE), placeholder_group_map


def match_dictionary_entry(step_text: str, dictionary_entry: str):
    """Match one concrete test step against one dictionary entry and return Pn values."""
    regex, placeholder_group_map = dictionary_entry_to_regex(dictionary_entry)
    match = regex.match(str(step_text or "").strip())
    if not match:
        return None

    param_map: Dict[str, str] = {}
    for placeholder_name, group_name in placeholder_group_map:
        value = match.groupdict().get(group_name)
        if value in (None, ""):
            value = match.groupdict().get(f"{group_name}_free", "")
        value = str(value or "").strip()
        if placeholder_name not in param_map or value:
            param_map[placeholder_name] = value

    return param_map


def apply_dictionary_translation(translation: str, param_map: Dict[str, str]) -> str:
    # Replace [P1], [P2], etc. in translation using captured parameter values.
    def replace_param(match):
        name = f"P{match.group(1)}".upper()
        return param_map.get(name, "")

    # Replace all placeholders.
    command = re.sub(r"\[P(\d+)\]", replace_param, str(translation or ""), flags=re.IGNORECASE)
    # Clean final command.
    command = clean_dictionary_command_text(command)

    # Add semicolon for CAPL command lines when missing.
    if command and not command.endswith((";", "{", "}", ":", ",")):
        command += ";"

    # Return command.
    return command


def capl_hex_payload_to_escaped_bytes(payload_text: str):
    # Extract byte tokens from a string like "22 E1 00".
    tokens = re.findall(r"(?:0x)?[0-9A-Fa-f]{2}", str(payload_text or ""))
    # Build CAPL escaped byte string like \\x22\\xE1\\x00.
    escaped = "".join(f"\\x{token.replace('0x', '').replace('0X', '').upper()}" for token in tokens)
    # Return escaped string and byte count.
    return escaped, len(tokens)


def capl_is_hex_token_payload(payload_text: str) -> bool:
    # Normalize payload text.
    payload = str(payload_text or "").strip()
    # Empty payload is not a valid token payload.
    if not payload:
        return False
    # Extract valid byte tokens.
    tokens = re.findall(r"(?:0x)?[0-9A-Fa-f]{2}", payload)
    # Remove valid tokens and spaces from payload.
    residue = re.sub(r"(?:0x)?[0-9A-Fa-f]{2}", "", payload)
    residue = residue.strip()
    # Return true only if all content is valid byte tokens separated by spaces.
    return bool(tokens) and residue == ""


def convert_send_uds_request_to_diag_commands(command: str) -> str:
    """
    Convert generated dictionary command:
        sendUdsRequest(ecu, "22 E1 00", requestLen);
    into:
        requestLen = getTokenCount("22 E1 00");
        diagResize(req, requestLen);
        diagSetPrimitiveData(req, "\\x22\\xE1\\x00", requestLen);
        diagSendRequest(req);

    If the command is not sendUdsRequest(...), it is returned unchanged.
    """
    # Match sendUdsRequest with quoted payload as second argument.
    match = re.search(
        r'^\s*sendUdsRequest\s*\(\s*([^,]+)\s*,\s*"([^"]*)"\s*,\s*([^)]+)\)\s*;?\s*$',
        str(command or ""),
        flags=re.IGNORECASE,
    )

    # Return original command if it is not a sendUdsRequest call.
    if not match:
        return command

    # Read the original payload string.
    payload = match.group(2).strip()

    # Convert payload to CAPL escaped byte string.
    escaped_bytes, byte_count = capl_hex_payload_to_escaped_bytes(payload)

    # If no bytes are detected, keep original command as a safe fallback.
    if byte_count <= 0:
        return command

    # Generate the diagnostic primitive commands.
    return (
        f'requestLen = getTokenCount("{payload}");\n'
        f'  diagResize(req, requestLen);\n'
        f'  diagSetPrimitiveData(req, "{escaped_bytes}", requestLen);\n'
        f'  diagSendRequest(req);'
    )


def convert_receive_uds_response_to_diag_commands(command: str) -> str:
    """
    Convert generated dictionary command:
        checkUdsResponse(resp, "62 E1 00");
    or:
        receiveUdsResponse(resp, "62 E1 00");
    into:
        responseLen = getTokenCount("62 E1 00");
        if(diagGetPrimitiveData(resp, buffer, elcount(buffer)) == responseLen && !memcmp(buffer, "\\x62\\xE1\\x00", responseLen))
          write("Response 62 E1 00 received");
        else
          testStepFail("Response check", "Expected response 62 E1 00 was not received");

    If the command is not a known receive/check function, it is returned unchanged.
    """
    # Match check/receive helper with quoted payload.
    match = re.search(
        r'^\s*(?:checkUdsResponse|receiveUdsResponse|expectUdsResponse)\s*\(\s*([^,]+)\s*,\s*"([^"]*)"\s*\)\s*;?\s*$',
        str(command or ""),
        flags=re.IGNORECASE,
    )

    # Return original command if it is not a known receive/check helper.
    if not match:
        return command

    # Read response object and payload.
    response_object = match.group(1).strip()
    payload = match.group(2).strip()

    # Convert payload to escaped byte string.
    escaped_bytes, byte_count = capl_hex_payload_to_escaped_bytes(payload)

    # If no bytes are detected, keep original command.
    if byte_count <= 0:
        return command

    # Generate response check commands.
    return (
        f'responseLen = getTokenCount("{payload}");\n'
        f'  if(diagGetPrimitiveData({response_object}, buffer, elcount(buffer)) == responseLen && !memcmp(buffer, "{escaped_bytes}", responseLen))\n'
        f'    write("Response {payload} received");\n'
        f'  else\n'
        f'    testStepFail("Response check", "Expected response {payload} was not received");'
    )


def convert_inline_response_check_tokens(command: str) -> str:
    """
    Convert inline CAPL response check code that still contains a readable token payload.
    Example input after dictionary parameter replacement:
        if(diagGetPrimitiveData(resp, buffer, elcount(buffer)) == 3 && !memcmp(buffer, "62 E1 00", 3))
          write("Response 62 E1 00 received");

    Example output:
        responseLen = getTokenCount("62 E1 00");
        if(diagGetPrimitiveData(resp, buffer, elcount(buffer)) == responseLen && !memcmp(buffer, "\\x62\\xE1\\x00", responseLen))
          write("Response 62 E1 00 received");
    """
    # Work on full command text.
    converted = str(command or "")

    # Find memcmp(buffer, "62 E1 00", 3) style readable payloads.
    pattern = re.compile(
        r'memcmp\s*\(\s*buffer\s*,\s*"([^"]+)"\s*,\s*(\d+|responseLen|getTokenCount\("[^"]*"\))\s*\)',
        flags=re.IGNORECASE,
    )

    # Search for first match.
    match = pattern.search(converted)

    # Return original if no memcmp payload found.
    if not match:
        return converted

    # Read payload.
    payload = match.group(1).strip()

    # Only convert if payload is readable hex tokens.
    if not capl_is_hex_token_payload(payload):
        return converted

    # Convert payload.
    escaped_bytes, byte_count = capl_hex_payload_to_escaped_bytes(payload)
    if byte_count <= 0:
        return converted

    # Replace hard-coded length comparison with responseLen where possible.
    converted = re.sub(
        r"diagGetPrimitiveData\s*\(\s*resp\s*,\s*buffer\s*,\s*elcount\s*\(\s*buffer\s*\)\s*\)\s*==\s*\d+",
        "diagGetPrimitiveData(resp, buffer, elcount(buffer)) == responseLen",
        converted,
        flags=re.IGNORECASE,
    )

    # Replace memcmp payload and length with escaped bytes and responseLen.
    converted = pattern.sub(f'memcmp(buffer, "{escaped_bytes}", responseLen)', converted)

    # Add responseLen line if not already available.
    if "responseLen" not in str(command or ""):
        converted = f'responseLen = getTokenCount("{payload}");\n  {converted}'

    # Return converted text.
    return converted


def convert_any_hex_token_strings_in_capl_command(command: str) -> str:
    """
    Automatically convert quoted request/response token strings in generated CAPL command text.

    Supported:
    - sendUdsRequest(ecu, "22 E1 00", requestLen);
    - checkUdsResponse(resp, "62 E1 00");
    - receiveUdsResponse(resp, "62 E1 00");
    - inline memcmp(buffer, "62 E1 00", 3)
    """
    # First convert high-level request helper.
    converted = convert_send_uds_request_to_diag_commands(command)

    # Then convert high-level response helper.
    converted = convert_receive_uds_response_to_diag_commands(converted)

    # Then convert inline memcmp response checks.
    converted = convert_inline_response_check_tokens(converted)

    # Return final converted command.
    return converted



def generate_capl_from_dictionary(testcases: Sequence[TestCaseRow], dictionary_rows: Sequence[Dict[str, str]]) -> str:
    # Build generation timestamp.
    generated_on = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    # Fields that contain executable test steps.
    step_fields = ["Pre Action", "Action", "Expectation", "Actual results", "Post Action"]
    # Sort dictionary rows by entry length so more specific entries match first.
    prepared_rows = sorted(
        [
            {
                "entry": str(row.get("entry", "") or "").strip(),
                "translation": str(row.get("translation", "") or "").strip(),
            }
            for row in dictionary_rows
            if str(row.get("entry", "") or "").strip() and str(row.get("translation", "") or "").strip()
        ],
        key=lambda row: len(row["entry"]),
        reverse=True,
    )

    # Create CAPL header.
    lines = [
        "/*",
        "Generated CAPL test module using Dictionary Translation.",
        f"Generated on: {generated_on}",
        f"Generated testcases: {sum(1 for tc in testcases if tc.is_valid_for_generation)}",
        f"Dictionary entries used: {len(prepared_rows)}",
        "",
        "Generation logic:",
        "- Original Excel step is copied as CAPL comment.",
        "- Dictionary Entry is matched against the concrete step.",
        "- Captured [P1], [P2], ... values are substituted into Translation.",
        "- Translation is written as CAPL command under the comment.",
        "*/",
        "",
        "includes",
        "{",
        "}",
        "",
        "variables",
        "{",
        "  char ecu[64];",
        "  long requestLen;",
        "  long responseLen;",
        "  byte buffer[4095];",
        "  diagRequest * req;",
        "  diagResponse * resp;",
        "}",
        "",
        "int getTokenCount(char request[])",
        "{",
        "  int count = 0, i;",
        "",
        "  for(i = 0; request[i] != 0; i++)",
        "    if(request[i] == ' ')",
        "      count++;",
        "",
        "  return count + 1;",
        "}",
        "",
    ]

    # Loop over testcases.
    for tc in testcases:
        if not tc.is_valid_for_generation:
            lines.append(f"/* Skipped Excel row {tc.excel_row}: {capl_dictionary_escape_comment(tc.generation_block_reason)} */")
            lines.append("")
            continue
        # Add testcase header.
        lines.append(f"testcase {tc.capl_name}()")
        lines.append("{")
        lines.append(f'  strncpy(ecu, "{capl_dictionary_escape_string(tc.ecu)}", elcount(ecu));')
        lines.append("  requestLen = 0;")
        lines.append(f"  // Test Case ID: {capl_dictionary_escape_comment(tc.tc_id)}")
        lines.append(f"  // Title: {capl_dictionary_escape_comment(tc.title)}")
        lines.append(f"  // Requirements: {capl_dictionary_escape_comment(tc.requirements)}")
        lines.append("")

        # Loop over step fields.
        for field_name in step_fields:
            field_value = tc.attributes.get(field_name, "")
            step_lines = split_lines(field_value)
            if not step_lines:
                continue

            lines.append(f"  // ===== {field_name} =====")

            # Loop over each step line.
            for step_line in step_lines:
                original_step = strip_leading_step_number(step_line)
                original_step = " ".join(str(original_step or "").split())
                if not original_step:
                    continue

                # Write original step as comment.
                lines.append(f"  // {field_name}: {capl_dictionary_escape_comment(step_line)}")

                # Try dictionary matches.
                generated_command = ""
                matched_entry = ""
                for row in prepared_rows:
                    param_map = match_dictionary_entry(original_step, row["entry"])
                    if param_map is not None:
                        generated_command = apply_dictionary_translation(row["translation"], param_map)
                        matched_entry = row["entry"]
                        break

                # Write command or TODO.
                if generated_command:
                    # Convert readable request/response token strings into CAPL diagnostic primitive code.
                    generated_command = convert_any_hex_token_strings_in_capl_command(generated_command)
                    lines.append(f"  // Matched dictionary entry: {capl_dictionary_escape_comment(matched_entry)}")
                    for command_line in str(generated_command).splitlines():
                        lines.append(f"  {command_line}")
                else:
                    lines.append("  // TODO: No dictionary translation matched this step.")

                lines.append("")

        # End testcase.
        lines.append("}")
        lines.append("")

    # Return joined CAPL text.
    return "\n".join(lines)


class CaplGeneratorGui(tk.Tk):
    def __init__(self) -> None:
        super().__init__()
        apply_pruefturbo_window_icon(self)
        self.title("PrüfTurbo - Core")
        self.geometry("1450x850")
        self.minsize(1150, 700)

        # This stores a value in the current object so other methods can use it later.
        self.source_var = tk.StringVar()
        # This stores a value in the current object so other methods can use it later.
        self.output_var = tk.StringVar()
        # This stores a value in the current object so other methods can use it later.
        self.status_var = tk.StringVar(value="Select an Excel .xlsx file. Output defaults to <input>_CAPL.can.")
        # This stores a value in the current object so other methods can use it later.
        self.testcases: List[TestCaseRow] = []
        # Track test cases selected for generation in the Generation tab checklist.
        self.generation_selected_tc_keys = set()
        # Track whether the Generation checklist has already been initialized for the current loaded specs.
        self.generation_selection_initialized = False
        # Text filter used in the Generation tab to show/select/deselect matching test case names.
        self.generation_filter_text_var = tk.StringVar(value="")
        # Enable regular-expression matching for the Generation tab filter.
        self.generation_filter_regex_var = tk.BooleanVar(value=False)
        # Select All state for the generation test-case checklist.
        self.generation_select_all_var = tk.BooleanVar(value=True)
        # Active standard dictionary used by the Test Case popup and updateable from the Dictionary tab.
        self.standard_test_step_dictionary = merge_standard_step_dictionaries(STANDARD_TEST_STEP_DICTIONARY)
        # This stores a value in the current object so other methods can use it later.
        self.testcase_item_map: Dict[str, TestCaseRow] = {}
        # Track whether the in-memory test specification was changed from the Test Case popup.
        self.specs_dirty = False
        # Load encrypted GUI settings. If the settings file does not exist or cannot be read, defaults are used.
        self.saved_gui_settings = self._load_encrypted_gui_settings()

        self._build_layout()

    def _build_layout(self) -> None:
        # Create a tab container so the GUI has separated workspaces.
        self.notebook = ttk.Notebook(self)
        # Place the tab container in the main window.
        self.notebook.pack(fill=tk.BOTH, expand=True)

        # Core workflow tabs are intentionally separated for clearer branching.
        self.test_case_tab = ttk.Frame(self.notebook)
        self.test_specs_tab = ttk.Frame(self.notebook)
        # Keep the old main_tab alias so existing helper methods continue to work.
        self.main_tab = self.test_specs_tab
        self.dictionary_tab = ttk.Frame(self.notebook)
        self.generation_tab = ttk.Frame(self.notebook)
        # Additional internal/optional tabs are still created but not shown in the Core branch.
        self.cdd_tab = ttk.Frame(self.notebook)
        self.regex_excel_tab = ttk.Frame(self.notebook)
        self.specs_optimizer_tab = ttk.Frame(self.notebook)
        self.hidden_replace_tab = ttk.Frame(self.notebook)
        # Track whether the hidden tab is currently visible.
        self.hidden_replace_tab_visible = False

        # Core branch: split the two combined product workflow tabs into four visible tabs.
        self.notebook.add(self.test_case_tab, text="Test Case")
        self.notebook.add(self.test_specs_tab, text="Test Specs")
        self.notebook.add(self.dictionary_tab, text="Dictionary")
        self.notebook.add(self.generation_tab, text="Generation")

        # Track tab visibility for the protected Ctrl+0 settings dialog.
        self.gui_tab_registry = [
            {"key": "test_case", "frame": self.test_case_tab, "text": "Test Case", "visible": True},
            {"key": "test_specs", "frame": self.test_specs_tab, "text": "Test Specs", "visible": True},
            {"key": "dictionary", "frame": self.dictionary_tab, "text": "Dictionary", "visible": True},
            {"key": "generation", "frame": self.generation_tab, "text": "Generation", "visible": True},
            {"key": "hidden_replace", "frame": self.hidden_replace_tab, "text": "Hidden Replace", "visible": False},
        ]

        # Create the file selection frame inside the Test Specs tab.
        top = ttk.LabelFrame(self.test_specs_tab, text="Files")
        # Place the file selection frame.
        top.pack(fill=tk.X, padx=10, pady=8)
        # Allow the path entry column to expand.
        top.columnconfigure(1, weight=1)

        # Show label for input Excel.
        ttk.Label(top, text="Input Excel (.xlsx):").grid(row=0, column=0, sticky=tk.W, padx=8, pady=6)
        # Show input Excel path entry.
        ttk.Entry(top, textvariable=self.source_var).grid(row=0, column=1, sticky=tk.EW, padx=8, pady=6)
        # Show button to browse input Excel.
        ttk.Button(top, text="Browse input...", command=self.browse_input).grid(row=0, column=2, padx=8, pady=6)

        # Show label for output CAPL.
        ttk.Label(top, text="Output CAPL (.can):").grid(row=1, column=0, sticky=tk.W, padx=8, pady=6)
        # Show output CAPL path entry.
        ttk.Entry(top, textvariable=self.output_var).grid(row=1, column=1, sticky=tk.EW, padx=8, pady=6)
        # Show button to browse output CAPL.
        ttk.Button(top, text="Browse output...", command=self.browse_output).grid(row=1, column=2, padx=8, pady=6)

        # Create main workflow button row.
        buttons = ttk.Frame(self.test_specs_tab)
        # Place main workflow button row.
        buttons.pack(fill=tk.X, padx=10, pady=(0, 8))
        # Reload Excel preview button.
        ttk.Button(buttons, text="Reload / Preview Tests", command=self.load_preview).pack(side=tk.LEFT, padx=(0, 8))
        # Expand all test tree nodes button.
