    def make_generation_testcase_key(self, tc: TestCaseRow, index: int) -> str:
        """Return a unique GUI selection key for one loaded Excel row.

        Important: the relation between test cases and requirements is many-to-many.
        Therefore the GUI must never use Requirement ID or TC ID as the Treeview item id,
        because these values can legitimately repeat across several rows.
        The Excel row plus the current list index gives every loaded test-case row its own checkbox.
        """
        safe_tc_id = re.sub(r"[^A-Za-z0-9_]+", "_", str(tc.tc_id or "TC")).strip("_") or "TC"
        return f"GEN_ROW_{tc.excel_row}_{index}_{safe_tc_id}"

    def generation_testcase_matches_filter(self, tc: TestCaseRow, key: str) -> bool:
        """Return True when a loaded test case matches the Generation tab name filter.

        The filter behaves like an Excel-style text filter by default:
        - Empty filter shows all rows.
        - Plain text is a case-insensitive contains search.
        - Wildcards are supported: * for any text, ? for one character.

        When the Regex checkbox is enabled, the filter text is treated as a regular
        expression and matched case-insensitively against Test Case ID + title/name.
        """
        pattern = ""
        if hasattr(self, "generation_filter_text_var"):
            pattern = (self.generation_filter_text_var.get() or "").strip()
        if not pattern:
            return True

        haystack_original = f"{tc.tc_id or ''} {tc.title or ''}"
        regex_enabled = bool(getattr(self, "generation_filter_regex_var", tk.BooleanVar(value=False)).get())

        if regex_enabled:
            try:
                return re.search(pattern, haystack_original, flags=re.IGNORECASE) is not None
            except re.error as exc:
                if hasattr(self, "status_var"):
                    self.status_var.set(f"Invalid Generation regex filter: {exc}")
                return False

        haystack = haystack_original.lower()
        pattern_lower = pattern.lower()

        try:
            if "*" in pattern_lower or "?" in pattern_lower:
                regex = ".*" + re.escape(pattern_lower).replace(r"\*", ".*").replace(r"\?", ".") + ".*"
                return re.search(regex, haystack) is not None
            return pattern_lower in haystack
        except Exception:
            return pattern_lower in haystack

    def update_generation_select_all_button_text(self) -> None:
        """Update the toggle button text based on whether all loaded rows are selected."""
        loaded_keys = list(getattr(self, "generation_testcase_loaded_keys", []) or [])
        loaded_key_set = set(loaded_keys)
        selected_keys = set(getattr(self, "generation_selected_tc_keys", set()) or set())
        all_selected = bool(loaded_key_set) and loaded_key_set.issubset(selected_keys)
        self.generation_select_all_var.set(all_selected)
        if hasattr(self, "generation_select_all_button"):
            self.generation_select_all_button.configure(text="Deselect All" if all_selected else "Select All")

    def refresh_generation_testcase_selection(self) -> None:
        """Refresh the Generation tab checklist from the currently loaded test cases."""
        if not hasattr(self, "generation_testcase_tree"):
            return

        existing_selection = set(getattr(self, "generation_selected_tc_keys", set()) or set())
        selection_initialized = bool(getattr(self, "generation_selection_initialized", False))
        testcase_key_map = {}
        loaded_keys = []
        visible_keys = []

        for index, tc in enumerate(self.testcases, start=1):
            key = self.make_generation_testcase_key(tc, index)
            loaded_keys.append(key)
            testcase_key_map[key] = tc
            if self.generation_testcase_matches_filter(tc, key):
                visible_keys.append(key)

        loaded_key_set = set(loaded_keys)
        self.generation_testcase_key_map = testcase_key_map
        self.generation_testcase_loaded_keys = loaded_keys
        self.generation_testcase_visible_keys = visible_keys

        if selection_initialized:
            self.generation_selected_tc_keys = existing_selection.intersection(loaded_key_set)
        else:
            # First load behavior: all newly loaded test cases are selected by default.
            self.generation_selected_tc_keys = set(loaded_keys)
            self.generation_selection_initialized = True

        for item_id in self.generation_testcase_tree.get_children(""):
            self.generation_testcase_tree.delete(item_id)

        for item_key in visible_keys:
            tc = testcase_key_map[item_key]
            checked = "☑" if item_key in self.generation_selected_tc_keys else "☐"
            tc_id = tc.tc_id or f"ROW_{tc.excel_row}"
            title = tc.title or "-"
            self.generation_testcase_tree.insert("", tk.END, iid=item_key, values=(checked, tc_id, title))

        self.update_generation_select_all_button_text()

    def on_generation_select_all_toggle(self) -> None:
        """Toggle all loaded test cases between selected and deselected."""
        loaded_keys = list(getattr(self, "generation_testcase_loaded_keys", []) or [])
        if not loaded_keys:
            loaded_keys = [
                self.make_generation_testcase_key(tc, index)
                for index, tc in enumerate(self.testcases, start=1)
            ]

        loaded_key_set = set(loaded_keys)
        selected_keys = set(getattr(self, "generation_selected_tc_keys", set()) or set())
        if loaded_key_set and loaded_key_set.issubset(selected_keys):
            self.generation_selected_tc_keys = set()
        else:
            self.generation_selected_tc_keys = set(loaded_keys)
        self.generation_selection_initialized = True
        self.refresh_generation_testcase_selection()

    def on_generation_select_all_changed(self) -> None:
        """Backward-compatible handler for older checkbutton wiring."""
        self.on_generation_select_all_toggle()

    def select_generation_filtered_matches(self) -> None:
        """Select only currently filtered/visible test cases in the Generation tab.

        This intentionally clears non-matching rows first, so a filter/pattern selection
        really controls what will be generated instead of leaving hidden rows selected.
        """
        if not hasattr(self, "generation_testcase_loaded_keys"):
            self.refresh_generation_testcase_selection()
        visible = set(getattr(self, "generation_testcase_visible_keys", []) or [])
        self.generation_selected_tc_keys = set(visible)
        self.generation_selection_initialized = True
        self.refresh_generation_testcase_selection()

    def deselect_generation_filtered_matches(self) -> None:
        """Deselect all currently filtered/visible test cases in the Generation tab."""
        if not hasattr(self, "generation_testcase_loaded_keys"):
            self.refresh_generation_testcase_selection()
        visible = set(getattr(self, "generation_testcase_visible_keys", []) or [])
        self.generation_selected_tc_keys.difference_update(visible)
        self.generation_selection_initialized = True
        self.refresh_generation_testcase_selection()

    def clear_generation_filter(self) -> None:
        """Clear the Generation tab text filter and show all loaded test cases again."""
        if hasattr(self, "generation_filter_text_var"):
            self.generation_filter_text_var.set("")
        self.refresh_generation_testcase_selection()

    def on_generation_testcase_tree_click(self, event) -> None:
        """Toggle a single test-case checkbox when the checklist is clicked."""
        if not hasattr(self, "generation_testcase_tree"):
            return

        row_id = self.generation_testcase_tree.identify_row(event.y)
        if not row_id:
            return

        if row_id in self.generation_selected_tc_keys:
            self.generation_selected_tc_keys.remove(row_id)
        else:
            self.generation_selected_tc_keys.add(row_id)

        self.generation_selection_initialized = True
        self.refresh_generation_testcase_selection()
        return "break"

    def get_selected_generation_testcases(self) -> List[TestCaseRow]:
        """Return only the checked test-case rows for CAPL generation.

        The selection is row-based, not requirement-based, so repeated requirement IDs are preserved.
        This method never falls back to generating all rows when the Generation tab exists;
        it returns an empty list if nothing is checked.
        """
        if not self.testcases:
            return []
        if not hasattr(self, "generation_testcase_key_map") or not getattr(self, "generation_testcase_key_map", None):
            self.refresh_generation_testcase_selection()
        selected_keys = set(getattr(self, "generation_selected_tc_keys", set()) or set())
        key_map = getattr(self, "generation_testcase_key_map", {})
        loaded_keys = getattr(self, "generation_testcase_loaded_keys", list(key_map.keys()))
        selected_rows = [key_map[key] for key in loaded_keys if key in selected_keys and key in key_map]
        if hasattr(self, "status_var"):
            self.status_var.set(f"Generation selection: {len(selected_rows)} of {len(loaded_keys)} test cases selected.")
        return selected_rows

    def set_generation_buttons_state(self, state: str) -> None:
        """Enable or dim/disable generation buttons while CAPL generation is running."""
        for button_name in ("dictionary_generate_button", "direct_generate_capl_button"):
            if hasattr(self, button_name):
                getattr(self, button_name).configure(state=state)


