    def browse_cdd_file(self) -> None:
        # Ask user to select a CDD or XML-like file.
        selected = filedialog.askopenfilename(
            title="Select CDD / CANdela file",
            filetypes=[
                ("CDD / XML files", "*.cdd *.xml *.txt"),
                ("CDD files", "*.cdd"),
                ("XML files", "*.xml"),
                ("All files", "*.*"),
            ],
        )
        # Stop if user cancelled.
        if not selected:
            return
        # Save selected path to GUI variable.
        self.cdd_file_var.set(selected)
        # Update status.
        self.status_var.set(f"CDD file selected: {selected}")

    def parse_cdd_file(self) -> None:
        # Try to parse the selected CDD file.
        try:
            # Read selected CDD file path.
            cdd_path = self.cdd_file_var.get().strip()
            # Warn if no file selected.
            if not cdd_path:
                messagebox.showwarning("Missing CDD file", "Please select a CDD file first.")
                return

            # Create path object.
            path = Path(cdd_path)
            # Validate file exists.
            if not path.exists():
                messagebox.showerror("CDD file not found", f"The selected CDD file does not exist:\n{path}")
                return

            # Read file text with fallback replacement for unsupported characters.
            cdd_text = path.read_text(encoding="utf-8", errors="replace")
            # Parse diagnostic and CAN content.
            self.cdd_items = parse_cdd_text(cdd_text)

            # Populate the CANdelaStudio-style explorer and details views.
            self.populate_cdd_candelastudio_view(path.name)

            # Group parsed items by type for statistics.
            grouped = {}
            # Loop over parsed items.
            for item in self.cdd_items:
                grouped.setdefault(item.get("type", "Unknown"), []).append(item)

            # Build statistics text.
            stat_parts = [f"{key}: {len(value)}" for key, value in sorted(grouped.items())]
            # Update CDD statistics.
            self.cdd_stats_var.set(
                f"CDD parsed: {path.name} | Total parsed items: {len(self.cdd_items)} | "
                + " | ".join(stat_parts)
            )
            # Update main status.
            self.status_var.set(f"CDD parsed successfully: {len(self.cdd_items)} item(s).")
            # Switch to CDD tab.
            self.notebook.select(self.cdd_tab)

        # Handle errors.
        except Exception as exc:
            # Update status.
            self.status_var.set("CDD parsing failed.")
            # Show error details.
            messagebox.showerror("CDD parsing failed", f"Could not parse CDD file.\n\nDetails:\n{type(exc).__name__}: {exc}")


    def populate_cdd_candelastudio_view(self, project_name: str = "CDD Project") -> None:
        # Clear navigation tree.
        for item in self.cdd_tree.get_children(""):
            self.cdd_tree.delete(item)

        # Clear details table.
        for item in self.cdd_detail_tree.get_children(""):
            self.cdd_detail_tree.delete(item)

        # Reset navigation mapping.
        self.cdd_nav_item_map = {}

        # Group items by CANdelaStudio-like categories.
        categories = {
            "Diagnostic Services": [],
            "Data Identifiers (DIDs)": [],
            "Routine Identifiers": [],
            "DTCs / Fault Memory": [],
            "CAN Communication": [],
            "CAN Messages": [],
            "CAN Signals": [],
            "Possible / Unclassified Objects": [],
        }

        # Classify parsed items into user-friendly navigation folders.
        for item in self.cdd_items:
            item_type = item.get("type", "")
            if item_type == "Diagnostic Service" or item_type == "Possible Service":
                categories["Diagnostic Services"].append(item)
            elif item_type == "DID" or item_type == "Possible DID/RID":
                categories["Data Identifiers (DIDs)"].append(item)
            elif item_type == "Routine ID":
                categories["Routine Identifiers"].append(item)
            elif item_type == "DTC" or item_type == "Possible DTC":
                categories["DTCs / Fault Memory"].append(item)
            elif item_type == "CAN Message":
                categories["CAN Messages"].append(item)
                categories["CAN Communication"].append(item)
            elif item_type == "CAN Signal":
                categories["CAN Signals"].append(item)
                categories["CAN Communication"].append(item)
            else:
                categories["Possible / Unclassified Objects"].append(item)

        # Create root project node.
        root = self.cdd_tree.insert(
            "",
            tk.END,
            text=project_name,
            values=(len(self.cdd_items),),
            open=True,
        )
        # Map root node to all parsed items.
        self.cdd_nav_item_map[root] = list(self.cdd_items)

        # Create main CANdelaStudio-like root folders.
        ecu_node = self.cdd_tree.insert(root, tk.END, text="ECU Diagnostic Description", values=("",), open=True)
        self.cdd_nav_item_map[ecu_node] = list(self.cdd_items)

        diag_node = self.cdd_tree.insert(ecu_node, tk.END, text="Diagnostics", values=("",), open=True)
        self.cdd_nav_item_map[diag_node] = (
            categories["Diagnostic Services"]
            + categories["Data Identifiers (DIDs)"]
            + categories["Routine Identifiers"]
            + categories["DTCs / Fault Memory"]
        )

        can_node = self.cdd_tree.insert(ecu_node, tk.END, text="CAN Communication", values=(len(categories["CAN Communication"]),), open=True)
        self.cdd_nav_item_map[can_node] = categories["CAN Communication"]

        # Add diagnostic folders.
        for folder_name in ["Diagnostic Services", "Data Identifiers (DIDs)", "Routine Identifiers", "DTCs / Fault Memory"]:
            folder_items = categories[folder_name]
            folder_node = self.cdd_tree.insert(diag_node, tk.END, text=folder_name, values=(len(folder_items),), open=False)
            self.cdd_nav_item_map[folder_node] = folder_items

            for parsed in sorted(folder_items, key=lambda x: (x.get("id", ""), x.get("name", ""))):
                child_text = f"{parsed.get('id', '')}  {parsed.get('name', '')}".strip()
                child = self.cdd_tree.insert(folder_node, tk.END, text=child_text, values=("",), open=False)
                self.cdd_nav_item_map[child] = [parsed]

        # Add CAN folders.
        for folder_name in ["CAN Messages", "CAN Signals"]:
            folder_items = categories[folder_name]
            folder_node = self.cdd_tree.insert(can_node, tk.END, text=folder_name, values=(len(folder_items),), open=False)
            self.cdd_nav_item_map[folder_node] = folder_items

            for parsed in sorted(folder_items, key=lambda x: (x.get("id", ""), x.get("name", ""))):
                child_text = f"{parsed.get('id', '')}  {parsed.get('name', '')}".strip()
                child = self.cdd_tree.insert(folder_node, tk.END, text=child_text, values=("",), open=False)
                self.cdd_nav_item_map[child] = [parsed]

        # Add unclassified folder only if it has content.
        unclassified = categories["Possible / Unclassified Objects"]
        if unclassified:
            unclassified_node = self.cdd_tree.insert(ecu_node, tk.END, text="Possible / Unclassified Objects", values=(len(unclassified),), open=False)
            self.cdd_nav_item_map[unclassified_node] = unclassified
            for parsed in sorted(unclassified, key=lambda x: (x.get("type", ""), x.get("id", ""), x.get("name", ""))):
                child_text = f"{parsed.get('type', '')}: {parsed.get('id', '')}  {parsed.get('name', '')}".strip()
                child = self.cdd_tree.insert(unclassified_node, tk.END, text=child_text, values=("",), open=False)
                self.cdd_nav_item_map[child] = [parsed]

        # Select root node by default.
        self.cdd_tree.selection_set(root)
        # Show root details by default.
        self.show_cdd_details_for_items(self.cdd_items)

    def on_cdd_tree_select(self, event=None) -> None:
        # Get selected navigation node.
        selected = self.cdd_tree.selection()

        # Stop if no node is selected.
        if not selected:
            return

        # Get parsed items mapped to the selected node.
        items = self.cdd_nav_item_map.get(selected[0], [])

        # Show details for selected navigation node.
        self.show_cdd_details_for_items(items)

    def show_cdd_details_for_items(self, items) -> None:
        # Clear details table.
        for item in self.cdd_detail_tree.get_children(""):
            self.cdd_detail_tree.delete(item)

        # Add selected items to details table.
        for parsed in sorted(items, key=lambda x: (x.get("type", ""), x.get("id", ""), x.get("name", ""))):
            self.cdd_detail_tree.insert(
                "",
                tk.END,
                values=(
                    parsed.get("type", ""),
                    parsed.get("id", ""),
                    parsed.get("name", ""),
                    parsed.get("source", ""),
                )
            )


    def export_cdd_parse_excel(self) -> None:
        # Try to export parsed CDD content to Excel.
        try:
            # Warn if no parsed items exist.
            if not getattr(self, "cdd_items", None):
                messagebox.showwarning("No CDD data", "Please parse a CDD file first.")
                return

            # Import datetime for timestamp.
            from datetime import datetime
            # Import Workbook to create Excel.
            from openpyxl import Workbook
            # Import styles for formatting.
            from openpyxl.styles import Alignment, Font

            # Create timestamp.
            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            # Ask user where to save export.
            target = filedialog.asksaveasfilename(
                title="Save CDD parse Excel",
                defaultextension=".xlsx",
                initialfile=f"CDD_Parse_{timestamp}.xlsx",
                filetypes=[("Excel workbook", "*.xlsx"), ("All files", "*.*")]
            )
            # Stop if user cancelled.
            if not target:
                return

            # Create workbook.
            wb = Workbook()
            # Get active sheet.
            ws = wb.active
            # Rename sheet.
            ws.title = "CDD Parsed Items"
            # Add header row.
            ws.append(["Type", "ID", "Name / Qualifier", "Parser Source"])

            # Add parsed item rows.
            for item in self.cdd_items:
                ws.append([
                    item.get("type", ""),
                    item.get("id", ""),
                    item.get("name", ""),
                    item.get("source", ""),
                ])

            # Freeze header row.
            ws.freeze_panes = "A2"
            # Enable filter.
            ws.auto_filter.ref = ws.dimensions

            # Format header.
            for cell in ws[1]:
                cell.font = Font(bold=True)
                cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)

            # Format all rows.
            for row_cells in ws.iter_rows(min_row=2):
                for cell in row_cells:
                    cell.alignment = Alignment(vertical="top", wrap_text=True)

            # Adjust column widths.
            for col_cells in ws.columns:
                col_letter = col_cells[0].column_letter
                max_len = len(str(col_cells[0].value or ""))
                for cell in col_cells[1:]:
                    value = "" if cell.value is None else str(cell.value)
                    max_len = max(max_len, min(len(value), 80))
                ws.column_dimensions[col_letter].width = max(14, min(max_len + 2, 70))

            # Save workbook.
            wb.save(target)

            # Update status.
            self.status_var.set(f"CDD parse exported: {target}")
            # Inform user.
            messagebox.showinfo("CDD export", f"CDD parse exported successfully:\n{target}")

        # Handle export errors.
        except Exception as exc:
            # Update status.
            self.status_var.set("CDD export failed.")
            # Show error details.
            messagebox.showerror("CDD export failed", f"Could not export CDD parse.\n\nDetails:\n{type(exc).__name__}: {exc}")



