    def browse_regex_excel_file(self) -> None:
        # Ask the user to select an Excel workbook.
        selected = filedialog.askopenfilename(
            title="Select Excel workbook for regex replacement",
            filetypes=[
                ("Excel workbooks", "*.xlsx *.xlsm"),
                ("All files", "*.*"),
            ],
        )
        # Stop if the user cancelled.
        if not selected:
            return
        # Store selected file path.
        self.regex_excel_file_var.set(selected)
        # Load sheet names from the workbook.
        self.load_regex_excel_sheets()
        # Switch to Excel Regex tab.
        self.notebook.select(self.regex_excel_tab)

    def load_regex_excel_sheets(self) -> None:
        # Try to load sheet names.
        try:
            # Read workbook path.
            workbook_path = self.regex_excel_file_var.get().strip()
            # Warn if no workbook was selected.
            if not workbook_path:
                messagebox.showwarning("Missing Excel file", "Please select an Excel workbook first.")
                return

            # Import openpyxl locally.
            from openpyxl import load_workbook

            # Load workbook in read-only mode to get sheet names quickly.
            wb = load_workbook(workbook_path, read_only=True, data_only=False)
            # Get sheet names.
            sheet_names = wb.sheetnames
            # Close workbook.
            wb.close()

            # Update combo box values.
            self.regex_sheet_combo["values"] = sheet_names
            # Select the first sheet if available.
            if sheet_names:
                self.regex_excel_sheet_var.set(sheet_names[0])

            # Update statistics.
            self.regex_excel_stats_var.set(f"Workbook loaded: {Path(workbook_path).name} | Sheets: {len(sheet_names)}")

        # Handle errors.
        except Exception as exc:
            # Show error message.
            messagebox.showerror("Load sheets failed", f"Could not load workbook sheets.\n\nDetails:\n{type(exc).__name__}: {exc}")

    def get_regex_target_cells(self, ws):
        # Read selected scope.
        scope = self.regex_scope_var.get().strip()
        # Create list for target cells.
        cells = []

        # Whole sheet scope uses all used cells.
        if scope == "Whole sheet":
            for row in ws.iter_rows():
                for cell in row:
                    cells.append(cell)
            return cells

        # Column scope uses one selected Excel column letter.
        if scope == "Column":
            column_letter = self.regex_column_var.get().strip().upper()
            if not column_letter:
                raise ValueError("Please enter a column letter, for example: J")
            for cell in ws[column_letter]:
                cells.append(cell)
            return cells

        # Row scope uses one selected row number.
        if scope == "Row":
            row_text = self.regex_row_var.get().strip()
            if not row_text.isdigit():
                raise ValueError("Please enter a valid row number, for example: 5")
            row_number = int(row_text)
            for cell in ws[row_number]:
                cells.append(cell)
            return cells

        # Cell scope uses one exact cell address.
        if scope == "Cell":
            cell_address = self.regex_cell_var.get().strip().upper()
            if not cell_address:
                raise ValueError("Please enter a cell address, for example: J5")
            cells.append(ws[cell_address])
            return cells

        # Reject unsupported scope.
        raise ValueError(f"Unsupported scope: {scope}")

    def collect_regex_excel_matches(self):
        # Read workbook path.
        workbook_path = self.regex_excel_file_var.get().strip()
        # Read sheet name.
        sheet_name = self.regex_excel_sheet_var.get().strip()
        # Read regex pattern.
        pattern_text = self.regex_pattern_var.get()
        # Read replacement text.
        replacement_text = self.regex_replacement_var.get()

        # Validate workbook path.
        if not workbook_path:
            raise ValueError("Please select an Excel workbook first.")
        # Validate sheet name.
        if not sheet_name:
            raise ValueError("Please select a worksheet first.")
        # Validate regex pattern.
        if not pattern_text:
            raise ValueError("Please enter a regular expression pattern.")

        # Compile regex pattern.
        compiled = re.compile(pattern_text)

        # Import openpyxl locally.
        from openpyxl import load_workbook

        # Load workbook normally so it can later be modified.
        wb = load_workbook(workbook_path)
        # Get selected worksheet.
        ws = wb[sheet_name]

        # Get target cells based on user scope.
        target_cells = self.get_regex_target_cells(ws)

        # Create list of replacements.
        matches = []

        # Loop over target cells.
        for cell in target_cells:
            # Only process non-empty string cells.
            if cell.value is None:
                continue

            # Convert cell value to text for regex processing.
            old_text = str(cell.value)

            # Apply regex replacement.
            new_text = compiled.sub(replacement_text, old_text)

            # If replacement changed the text, record it.
            if new_text != old_text:
                matches.append((cell.coordinate, old_text, new_text, cell))

        # Return workbook, worksheet, and collected matches.
        return wb, ws, matches

    def preview_regex_excel_replacement(self) -> None:
        # Try to preview replacement matches.
        try:
            # Clear preview table.
            for item in self.regex_preview_tree.get_children(""):
                self.regex_preview_tree.delete(item)

            # Collect matches.
            wb, ws, matches = self.collect_regex_excel_matches()
            # Close workbook because preview does not save.
            wb.close()

            # Fill preview table.
            for coordinate, old_text, new_text, _cell in matches[:1000]:
                self.regex_preview_tree.insert(
                    "",
                    tk.END,
                    values=(coordinate, old_text, new_text)
                )

            # Update statistics.
            self.regex_excel_stats_var.set(
                f"Preview completed | Sheet: {self.regex_excel_sheet_var.get()} | "
                f"Matches: {len(matches)} | Showing: {min(len(matches), 1000)}"
            )

            # Inform if no matches.
            if not matches:
                messagebox.showinfo("Regex preview", "No matching cells found.")

        # Handle preview errors.
        except Exception as exc:
            # Show error message.
            messagebox.showerror("Regex preview failed", f"Could not preview regex replacement.\n\nDetails:\n{type(exc).__name__}: {exc}")

    def apply_regex_excel_replacement(self) -> None:
        # Try to apply regex replacements and save a copy.
        try:
            # Clear preview table.
            for item in self.regex_preview_tree.get_children(""):
                self.regex_preview_tree.delete(item)

            # Collect matches and workbook object.
            wb, ws, matches = self.collect_regex_excel_matches()

            # Stop if there are no matches.
            if not matches:
                wb.close()
                messagebox.showinfo("Regex replacement", "No matching cells found. Nothing was saved.")
                return

            # Apply all replacements to the workbook cells.
            for coordinate, old_text, new_text, cell in matches:
                cell.value = new_text

            # Build default output name.
            source_path = Path(self.regex_excel_file_var.get().strip())
            default_name = f"{source_path.stem}_regex_replaced{source_path.suffix}"

            # Ask user where to save the modified workbook copy.
            target = filedialog.asksaveasfilename(
                title="Save regex-replaced Excel copy",
                defaultextension=source_path.suffix or ".xlsx",
                initialfile=default_name,
                filetypes=[
                    ("Excel workbooks", "*.xlsx *.xlsm"),
                    ("All files", "*.*"),
                ],
            )

            # If user cancels, close workbook and stop.
            if not target:
                wb.close()
                self.regex_excel_stats_var.set("Regex replacement cancelled before save.")
                return

            # Save workbook copy.
            wb.save(target)
            # Close workbook.
            wb.close()

            # Fill preview table with changed cells.
            for coordinate, old_text, new_text, _cell in matches[:1000]:
                self.regex_preview_tree.insert(
                    "",
                    tk.END,
                    values=(coordinate, old_text, new_text)
                )

            # Update statistics.
            self.regex_excel_stats_var.set(
                f"Replacement saved | Sheet: {self.regex_excel_sheet_var.get()} | "
                f"Changed cells: {len(matches)} | File: {target}"
            )
            # Update main status.
            self.status_var.set(f"Regex replacement saved: {target}")
            # Inform user.
            messagebox.showinfo(
                "Regex replacement completed",
                f"Replacement completed successfully.\n\nChanged cells: {len(matches)}\nSaved copy:\n{target}"
            )

        # Handle replacement errors.
        except Exception as exc:
            # Show error message.
            messagebox.showerror("Regex replacement failed", f"Could not apply regex replacement.\n\nDetails:\n{type(exc).__name__}: {exc}")



