    def load_specs_optimizer_sheets(self) -> None:
        # Try to load sheet names.
        try:
            # Read workbook path.
            workbook_path = self.specs_opt_file_var.get().strip()
            # Validate workbook path.
            if not workbook_path:
                messagebox.showwarning("Missing Excel file", "Please select an Excel workbook first.")
                return

            # Import openpyxl.
            from openpyxl import load_workbook

            # Load workbook read-only to get sheets.
            wb = load_workbook(workbook_path, read_only=True, data_only=False)
            # Read sheet names.
            sheet_names = wb.sheetnames
            # Close workbook.
            wb.close()

            # Update sheet combo.
            self.specs_opt_sheet_combo["values"] = sheet_names
            # Select TestSpecs if available, otherwise first sheet.
            if "TestSpecs" in sheet_names:
                self.specs_opt_sheet_var.set("TestSpecs")
            elif sheet_names:
                self.specs_opt_sheet_var.set(sheet_names[0])

            # Update statistics.
            self.specs_opt_stats_var.set(f"Workbook loaded: {Path(workbook_path).name} | Sheets: {len(sheet_names)}")

        # Handle errors.
        except Exception as exc:
            messagebox.showerror("Load sheets failed", f"Could not load workbook sheets.\n\nDetails:\n{type(exc).__name__}: {exc}")

    def get_specs_optimizer_columns(self):
        # Read columns text.
        raw = self.specs_opt_columns_var.get().strip()
        # Validate columns.
        if not raw:
            raise ValueError("Please enter at least one column letter, for example: J or I,J,K,L,M")
        # Split by comma or semicolon.
        parts = re.split(r"[,;]+", raw)
        # Clean and uppercase letters.
        columns = [part.strip().upper() for part in parts if part.strip()]
        # Return column list.
        return columns

    def build_specs_optimization_preview(self):
        # Read workbook path.
        workbook_path = self.specs_opt_file_var.get().strip()
        # Read selected sheet.
        sheet_name = self.specs_opt_sheet_var.get().strip()
        # Validate workbook path.
        if not workbook_path:
            raise ValueError("Please select an Excel workbook first.")
        # Validate sheet name.
        if not sheet_name:
            raise ValueError("Please select a worksheet first.")

        # Import openpyxl.
        from openpyxl import load_workbook

        # Load workbook.
        wb = load_workbook(workbook_path)
        # Get worksheet.
        ws = wb[sheet_name]
        # Get step columns.
        columns = self.get_specs_optimizer_columns()

        # Store preview rows.
        preview_rows = []
        # Store grouped dictionary entries.
        groups = {}

        # Loop through selected columns.
        for column_letter in columns:
            # Loop through cells in the column, skipping header row 1.
            for cell in ws[column_letter]:
                # Skip header row.
                if cell.row == 1:
                    continue
                # Skip empty cells.
                if cell.value is None:
                    continue

                # Split multiline cell into steps.
                lines = split_step_cell_preserve_lines(cell.value)

                # Loop over each step line.
                for line_index, line in enumerate(lines, start=1):
                    # Optionally add square brackets around detected variable parts before grouping.
                    if getattr(self, "specs_opt_auto_brackets_var", tk.BooleanVar(value=True)).get():
                        bracketed_line = auto_add_square_brackets_for_specs_step(line)
                    else:
                        bracketed_line = line

                    # Build optimized dictionary-style step from the bracketed or original line.
                    optimized, params = optimize_specs_step_pattern(bracketed_line)

                    # Add preview row only when parameters were detected.
                    if params:
                        location = f"{cell.coordinate} / line {line_index}"
                        preview_entry = {
                            "cell": cell.coordinate,
                            "row": cell.row,
                            "column": column_letter,
                            "line_index": line_index,
                            "original": line,
                            "bracketed": bracketed_line,
                            "optimized": optimized,
                            "params": params,
                        }
                        preview_rows.append(preview_entry)

                        group = groups.setdefault(
                            optimized,
                            {
                                "optimized": optimized,
                                "count": 0,
                                "examples": [],
                                "locations": [],
                                "params": [],
                            }
                        )
                        group["count"] += 1
                        if bracketed_line != line:
                            group["examples"].append(f"{line}  →  {bracketed_line}")
                        else:
                            group["examples"].append(line)
                        group["locations"].append(location)
                        group["params"].append(" | ".join(params))

        # Close workbook without saving.
        wb.close()
        # Return preview rows and groups.
        return preview_rows, groups

    def preview_specs_optimization(self) -> None:
        # Try preview generation.
        try:
            # Clear preview tree.
            for item in self.specs_opt_tree.get_children(""):
                self.specs_opt_tree.delete(item)

            # Clear selectable row state for a new preview.
            self.specs_opt_selected_items = set()
            self.specs_opt_selectable_row_map = {}
            self.specs_opt_filtered_items = set()

            # Update filter column choices from selected optimizer columns.
            try:
                cols = ["All"] + self.get_specs_optimizer_columns()
                self.specs_filter_column_combo["values"] = cols
                if self.specs_filter_column_var.get() not in cols:
                    self.specs_filter_column_var.set("All")
            except Exception:
                pass

            # Build preview rows and dictionary groups.
            preview_rows, groups = self.build_specs_optimization_preview()
            # Store preview.
            self.specs_opt_preview_rows = preview_rows
            # Store groups.
            self.specs_opt_dictionary_groups = groups

            # Add grouped tree nodes.
            for optimized in sorted(groups.keys(), key=lambda x: x.lower()):
                group = groups[optimized]
                root = self.specs_opt_tree.insert(
                    "",
                    tk.END,
                    text=optimized,
                    values=("", optimized, group["count"], ""),
                    open=False,
                )

                for example, location, params in zip(group["examples"], group["locations"], group["params"]):
                    # Create selectable ID for automatic preview row.
                    auto_item_id = f"auto_{len(self.specs_opt_selectable_row_map)}"
                    # Try to resolve cell and line from the location string.
                    location_cell = str(location).split(" / line ")[0].strip()
                    try:
                        location_line = int(str(location).split(" / line ")[1].strip())
                    except Exception:
                        location_line = None
                    # Derive column letters from the cell coordinate.
                    location_column = re.sub(r"\d+", "", location_cell)
                    # Store automatic preview row as selectable for manual grouping.
                    self.specs_opt_selectable_row_map[auto_item_id] = {
                        "cell": location_cell,
                        "line_index": location_line,
                        "column": location_column,
                        "original": example,
                        "optimized": optimized,
                    }
                    self.specs_opt_tree.insert(
                        root,
                        tk.END,
                        iid=auto_item_id,
                        text=example,
                        values=("☐ Select", optimized, "", f"{location} | {params}"),
                        open=False,
                    )

            # Populate manual selectable rows under the preview tree.
            self.populate_specs_manual_selection_rows()
            self.refresh_specs_optimizer_manual_rows()

            # Update statistics.
            auto_brackets_state = "ON" if getattr(self, "specs_opt_auto_brackets_var", tk.BooleanVar(value=True)).get() else "OFF"
            self.specs_opt_stats_var.set(
                f"Preview completed | Auto []: {auto_brackets_state} | "
                f"Standard entries: {len(groups)} | Replacement candidates: {len(preview_rows)}"
            )

            # Inform if nothing found.
            if not preview_rows:
                messagebox.showinfo("Specs Optimizer", "No optimizable step patterns found.")

            # Switch to specs optimizer tab.
            self.notebook.select(self.specs_optimizer_tab)

            # Inform user how manual grouping works.
            messagebox.showinfo(
                "Manual grouping usage",
                "To manually group similar entries:\n\n"
                "1. Click any preview row or manual candidate in the Select column\n"
                "2. The row should show ☑ Selected\n"
                "3. Select at least two similar rows\n"
                "4. Press 'Group Selected'"
            )

        # Handle errors.
        except Exception as exc:
            messagebox.showerror("Specs optimization preview failed", f"Could not build preview.\n\nDetails:\n{type(exc).__name__}: {exc}")

    def populate_specs_manual_selection_rows(self):
        # Clear current manual row storage.
        self.specs_opt_manual_rows = []
        # Read workbook path.
        workbook_path = self.specs_opt_file_var.get().strip()
        # Read selected sheet.
        sheet_name = self.specs_opt_sheet_var.get().strip()
        # Validate workbook path.
        if not workbook_path or not sheet_name:
            return

        # Import openpyxl.
        from openpyxl import load_workbook

        # Load workbook.
        wb = load_workbook(workbook_path)
        # Get worksheet.
        ws = wb[sheet_name]
        # Get selected columns.
        columns = self.get_specs_optimizer_columns()

        # Loop over columns.
        for column_letter in columns:
            # Loop over cells.
            for cell in ws[column_letter]:
                # Skip header row.
                if cell.row == 1:
                    continue
                # Skip empty cells.
                if cell.value is None:
                    continue
                # Split cell lines.
                lines = split_step_cell_preserve_lines(cell.value)
                # Loop over lines.
                for line_index, line in enumerate(lines, start=1):
                    # Store row information.
                    self.specs_opt_manual_rows.append({
                        "cell": cell.coordinate,
                        "row": cell.row,
                        "column": column_letter,
                        "line_index": line_index,
                        "original": line,
                    })

        # Close workbook.
        wb.close()

    def refresh_specs_optimizer_manual_rows(self):
        # Add manual selectable root folder.
        manual_root = self.specs_opt_tree.insert(
            "",
            tk.END,
            text="Manual selection candidates",
            values=("", "", len(self.specs_opt_manual_rows), "Click rows in Select column to toggle ☑"),
            open=True,
        )

        # Add every step line with checkbox-like value.
        for idx, row in enumerate(self.specs_opt_manual_rows):
            item_id = f"manual_{idx}"
            selected_mark = "☑ Selected" if item_id in self.specs_opt_selected_items else "☐ Select"
            # Store manual candidate in the common selectable map.
            self.specs_opt_selectable_row_map[item_id] = row
            self.specs_opt_tree.insert(
                manual_root,
                tk.END,
                iid=item_id,
                text=row.get("original", ""),
                values=(selected_mark, "", "", f"{row.get('cell')} / line {row.get('line_index')}"),
                open=False,
            )

    def on_specs_optimizer_tree_click(self, event) -> None:
        # Identify clicked row.
        item = self.specs_opt_tree.identify_row(event.y)
        # Identify clicked column.
        column = self.specs_opt_tree.identify_column(event.x)

        # Only toggle rows that are registered as selectable.
        # This includes automatic preview entries and manual selection candidates.
        if not item or item not in getattr(self, "specs_opt_selectable_row_map", {}):
            return

        if column not in ("#0", "#1"):
            return

        # Toggle selected state.
        if item in self.specs_opt_selected_items:
            self.specs_opt_selected_items.remove(item)
        else:
            self.specs_opt_selected_items.add(item)

        # Update check mark in tree.
        values = list(self.specs_opt_tree.item(item, "values"))
        if values:
            values[0] = "☑ Selected" if item in self.specs_opt_selected_items else "☐ Select"
            self.specs_opt_tree.item(item, values=values)

    def group_selected_specs_entries(self) -> None:
        # Collect selected rows from automatic preview and manual candidates.
        selected_rows = []
        selectable_map = getattr(self, "specs_opt_selectable_row_map", {})

        # Loop over selected item IDs in stable visual-like order.
        for item_id in list(self.specs_opt_selected_items):
            row = selectable_map.get(item_id)
            if row:
                selected_rows.append(row)

        # Sort selected rows by cell and line number where available.
        selected_rows = sorted(
            selected_rows,
            key=lambda row: (str(row.get("cell", "")), int(row.get("line_index") or 0), str(row.get("original", "")))
        )

        # Require at least two selected rows.
        if len(selected_rows) < 2:
            messagebox.showinfo("Manual grouping", "Please select at least two similar step entries from the preview tree.")
            return

        # Build common pattern from selected lines.
        selected_lines = [row["original"] for row in selected_rows]
        pattern, params_per_line = build_manual_group_pattern(selected_lines)

        # Stop if no pattern generated.
        if not pattern:
            messagebox.showwarning("Manual grouping", "Could not build a grouping pattern from the selected entries.")
            return

        # Store manual group in dictionary groups.
        group = self.specs_opt_dictionary_groups.setdefault(
            pattern,
            {
                "optimized": pattern,
                "count": 0,
                "examples": [],
                "locations": [],
                "params": [],
                "manual": True,
            }
        )

        # Add selected rows to preview rows and group.
        for row, params in zip(selected_rows, params_per_line):
            location = f"{row.get('cell', '')} / line {row.get('line_index', '')}"
            preview_entry = {
                "cell": row.get("cell", ""),
                "row": row.get("row", ""),
                "column": row.get("column", ""),
                "line_index": row.get("line_index", ""),
                "original": row.get("original", ""),
                "bracketed": pattern,
                "optimized": pattern,
                "params": params,
                "manual_group": True,
            }
            self.specs_opt_preview_rows.append(preview_entry)
            group["count"] += 1
            group["examples"].append(row.get("original", ""))
            group["locations"].append(location)
            group["params"].append(" | ".join(params))

        # Add a manual grouping node in the tree.
        root = self.specs_opt_tree.insert(
            "",
            tk.END,
            text=f"Manual Group: {pattern}",
            values=("", pattern, group["count"], "Manual grouping from selected preview rows"),
            open=True,
        )

        # Add children under manual group.
        for row, params in zip(selected_rows, params_per_line):
            location = f"{row.get('cell', '')} / line {row.get('line_index', '')}"
            self.specs_opt_tree.insert(
                root,
                tk.END,
                text=row.get("original", ""),
                values=("☑ Selected", pattern, "", f"{location} | {' | '.join(params)}"),
                open=False,
            )

        # Update statistics.
        self.specs_opt_stats_var.set(
            f"Manual group created | Pattern: {pattern} | Selected entries: {len(selected_rows)}"
        )
        # Inform user.
        messagebox.showinfo(
            "Manual grouping created",
            f"Created manual grouping:\n\n{pattern}\n\nSelected entries: {len(selected_rows)}"
        )


    def on_specs_optimizer_tree_right_click(self, event) -> None:
        # Detect clicked tree row.
        item = self.specs_opt_tree.identify_row(event.y)

        # Stop if no row was clicked.
        if not item:
            return

        # Select the clicked row visually.
        self.specs_opt_tree.selection_set(item)

        # Store the current right-click row for menu actions.
        self.specs_opt_context_item = item

        # Show popup menu near mouse cursor.
        try:
            self.specs_opt_context_menu.tk_popup(event.x_root, event.y_root)
        finally:
            self.specs_opt_context_menu.grab_release()

    def copy_specs_selected_text_to_filter(self) -> None:
        # Read the selected context-menu row.
        item = getattr(self, "specs_opt_context_item", None)

        # Stop if there is no selected row.
        if not item or not self.specs_opt_tree.exists(item):
            return

        # Read tree item text and values.
        item_text = str(self.specs_opt_tree.item(item, "text") or "").strip()
        item_values = self.specs_opt_tree.item(item, "values") or []

        # Try to build meaningful filter text.
        filter_text = item_text

        # If the selected row is a grouped/manual row, prefer optimized text.
        if item_values:
            try:
                optimized_value = str(item_values[1]).strip()
                if optimized_value:
                    filter_text = optimized_value
            except Exception:
                pass

        # Clean helper labels.
        filter_text = filter_text.replace("☑ Selected", "").replace("☐ Select", "").replace("☐ Filtered", "").strip()

        # Stop if no usable text exists.
        if not filter_text:
            messagebox.showinfo("Copy to filter", "No usable text found in the selected row.")
            return

        # Copy selected text into the filter field.
        self.specs_filter_text_var.set(filter_text)

        # Update statistics/status.
        self.specs_opt_stats_var.set(f"Copied selected text to filter: {filter_text}")
        self.status_var.set(f"Filter text updated from selected preview row.")

        # Inform user.
        messagebox.showinfo(
            "Copy to filter",
            f"The selected text was copied to the filter field:\n\n{filter_text}"
        )


    def apply_specs_filter(self) -> None:
        # Clear old filtered results.
        self.specs_opt_filtered_items = set()

        # Read filter text.
        filter_text_raw = self.specs_filter_text_var.get().strip()
        # Read normal lowercase filter text.
        filter_text = filter_text_raw.lower()
        # Read selected column filter.
        filter_column = self.specs_filter_column_var.get().strip().upper()
        # Read whether regular-expression matching is enabled.
        use_regex = getattr(self, "specs_filter_regex_var", tk.BooleanVar(value=False)).get()

        # Stop if no filter text exists.
        if not filter_text_raw:
            self.specs_opt_stats_var.set("Filter cleared. Enter text and press Apply Filter.")
            return

        # Compile regex if regex mode is enabled.
        compiled_regex = None
        if use_regex:
            try:
                compiled_regex = re.compile(filter_text_raw, flags=re.IGNORECASE)
            except re.error as exc:
                messagebox.showerror(
                    "Invalid regular expression",
                    f"The filter regular expression is invalid.\n\nDetails:\n{exc}"
                )
                self.specs_opt_stats_var.set("Regex filter failed: invalid regular expression.")
                return

        # Loop over all selectable rows.
        for item_id, row in getattr(self, "specs_opt_selectable_row_map", {}).items():
            # Apply optional column filter.
            if filter_column != "ALL" and str(row.get("column", "")).upper() != filter_column:
                continue

            # Build searchable text from important row fields.
            haystack_original = " ".join([
                str(row.get("original", "")),
                str(row.get("optimized", "")),
                str(row.get("cell", "")),
                str(row.get("column", "")),
            ])

            # Check match using regex or normal contains.
            if use_regex:
                matched = compiled_regex.search(haystack_original) is not None
            else:
                matched = filter_text in haystack_original.lower()

            # Store matching item IDs.
            if matched:
                self.specs_opt_filtered_items.add(item_id)

        # Update visual state of all selectable rows.
        for item_id in getattr(self, "specs_opt_selectable_row_map", {}):
            if not self.specs_opt_tree.exists(item_id):
                continue
            values = list(self.specs_opt_tree.item(item_id, "values"))
            if not values:
                continue
            if item_id in self.specs_opt_selected_items:
                values[0] = "☑ Selected"
            elif item_id in self.specs_opt_filtered_items:
                values[0] = "☐ Filtered"
            else:
                values[0] = "☐ Select"
            self.specs_opt_tree.item(item_id, values=values)

        # Update statistics.
        mode_text = "Regex" if use_regex else "Contains"
        self.specs_opt_stats_var.set(
            f"Filter applied ({mode_text}) | Text: '{filter_text_raw}' | "
            f"Column: {self.specs_filter_column_var.get()} | Matches: {len(self.specs_opt_filtered_items)}"
        )

        # Inform if there are no matches.
        if not self.specs_opt_filtered_items:
            messagebox.showinfo("Filter", "No matching entries found for the current filter.")

    def select_filtered_specs_entries(self) -> None:
        if not getattr(self, "specs_opt_filtered_items", None) and self.specs_filter_text_var.get().strip():
            self.apply_specs_filter()

        if not getattr(self, "specs_opt_filtered_items", None):
            messagebox.showinfo("Select filtered", "No filtered entries to select. Apply a filter first.")
            return

        for item_id in self.specs_opt_filtered_items:
            self.specs_opt_selected_items.add(item_id)
            if self.specs_opt_tree.exists(item_id):
                values = list(self.specs_opt_tree.item(item_id, "values"))
                if values:
                    values[0] = "☑ Selected"
                    self.specs_opt_tree.item(item_id, values=values)

        self.specs_opt_stats_var.set(
            f"Selected filtered entries: {len(self.specs_opt_filtered_items)} | "
            f"Total selected: {len(self.specs_opt_selected_items)}"
        )

    def clear_specs_selection(self) -> None:
        self.specs_opt_selected_items = set()
        for item_id in getattr(self, "specs_opt_selectable_row_map", {}):
            if not self.specs_opt_tree.exists(item_id):
                continue
            values = list(self.specs_opt_tree.item(item_id, "values"))
            if not values:
                continue
            values[0] = "☐ Filtered" if item_id in getattr(self, "specs_opt_filtered_items", set()) else "☐ Select"
            self.specs_opt_tree.item(item_id, values=values)
        self.specs_opt_stats_var.set("Selection cleared.")

    def export_optimized_specs_workbook(self) -> None:
        self.apply_specs_optimization_save_copy()


    def apply_specs_optimization_save_copy(self) -> None:
        # Try applying preview and saving a copy.
        try:
            # Ensure preview exists.
            if not getattr(self, "specs_opt_preview_rows", None):
                self.preview_specs_optimization()

            # Stop if no preview exists.
            if not getattr(self, "specs_opt_preview_rows", None):
                return

            # Ask confirmation before modifying workbook copy.
            confirm = messagebox.askyesno(
                "Confirm specs optimization",
                "Apply the previewed standard dictionary replacements and save a modified Excel copy?"
            )
            # Stop if user rejected.
            if not confirm:
                self.specs_opt_stats_var.set("Apply cancelled by user.")
                return

            # Import openpyxl.
            from openpyxl import load_workbook

            # Read workbook path and sheet.
            workbook_path = self.specs_opt_file_var.get().strip()
            sheet_name = self.specs_opt_sheet_var.get().strip()
            # Load workbook.
            wb = load_workbook(workbook_path)
            # Get worksheet.
            ws = wb[sheet_name]
            # Get columns.
            columns = self.get_specs_optimizer_columns()

            # Build manual/preview override map keyed by cell and line number.
            preview_override_map = {}
            for preview_row in getattr(self, "specs_opt_preview_rows", []):
                preview_override_map[(preview_row.get("cell"), preview_row.get("line_index"))] = preview_row.get("optimized")

            # Count changed cells.
            changed_cells = 0
            # Count changed lines.
            changed_lines = 0

            # Loop over selected columns.
            for column_letter in columns:
                # Loop through cells in column.
                for cell in ws[column_letter]:
                    # Skip header row.
                    if cell.row == 1:
                        continue
                    # Skip empty cells.
                    if cell.value is None:
                        continue

                    # Split cell lines.
                    lines = split_step_cell_preserve_lines(cell.value)
                    # Skip empty.
                    if not lines:
                        continue

                    # Store new lines.
                    new_lines = []
                    # Track cell change.
                    cell_changed = False

                    # Optimize each line.
                    for line_index, line in enumerate(lines, start=1):
                        # First check if this line has a manually confirmed preview override.
                        override = preview_override_map.get((cell.coordinate, line_index))
                        if override:
                            new_lines.append(override)
                            cell_changed = True
                            changed_lines += 1
                            continue

                        # Optionally add square brackets around detected variable parts before grouping.
                        if getattr(self, "specs_opt_auto_brackets_var", tk.BooleanVar(value=True)).get():
                            bracketed_line = auto_add_square_brackets_for_specs_step(line)
                        else:
                            bracketed_line = line

                        # Build optimized dictionary-style step.
                        optimized, params = optimize_specs_step_pattern(bracketed_line)
                        # Use optimized line when parameters exist; otherwise keep original line.
                        if params:
                            new_lines.append(optimized)
                            cell_changed = True
                            changed_lines += 1
                        else:
                            new_lines.append(line)

                    # Update cell if changed.
                    if cell_changed:
                        cell.value = "\n".join(new_lines)
                        changed_cells += 1

            # Build default output name.
            source_path = Path(workbook_path)
            default_name = f"{source_path.stem}_SpecsOptimized{source_path.suffix}"

            # Ask where to save copy.
            target = filedialog.asksaveasfilename(
                title="Save optimized specs workbook copy",
                defaultextension=source_path.suffix or ".xlsx",
                initialfile=default_name,
                filetypes=[("Excel workbooks", "*.xlsx *.xlsm"), ("All files", "*.*")],
            )

            # Stop if cancelled.
            if not target:
                wb.close()
                self.specs_opt_stats_var.set("Apply cancelled before save.")
                return

            # Save workbook copy.
            wb.save(target)
            # Close workbook.
            wb.close()

            # Update statistics.
            self.specs_opt_stats_var.set(
                f"Applied and saved | Changed cells: {changed_cells} | Changed lines: {changed_lines} | File: {target}"
            )
            # Update global status.
            self.status_var.set(f"Specs optimization saved: {target}")
            # Inform user.
            messagebox.showinfo(
                "Specs optimization completed",
                f"Specs optimization completed successfully.\n\nChanged cells: {changed_cells}\nChanged lines: {changed_lines}\nSaved copy:\n{target}"
            )

        # Handle errors.
        except Exception as exc:
            messagebox.showerror("Specs optimization apply failed", f"Could not apply specs optimization.\n\nDetails:\n{type(exc).__name__}: {exc}")

    def export_specs_optimizer_dictionary(self) -> None:
        # Try exporting standard dictionary groups.
        try:
            # Ensure preview exists.
            if not getattr(self, "specs_opt_dictionary_groups", None):
                self.preview_specs_optimization()

            # Stop if no groups.
            if not getattr(self, "specs_opt_dictionary_groups", None):
                return

            # Import workbook and formatting.
            from datetime import datetime
            from openpyxl import Workbook
            from openpyxl.styles import Alignment, Font

            # Create timestamp.
            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            # Ask where to save.
            target = filedialog.asksaveasfilename(
                title="Save specs standard dictionary",
                defaultextension=".xlsx",
                initialfile=f"Specs_Standard_Dictionary_{timestamp}.xlsx",
                filetypes=[("Excel workbook", "*.xlsx"), ("All files", "*.*")],
            )

            # Stop if cancelled.
            if not target:
                return

            # Create workbook.
            wb = Workbook()
            # Get worksheet.
            ws = wb.active
            # Rename sheet.
            ws.title = "Standard Dictionary"
            # Add headers.
            ws.append(["Standard Dictionary Entry", "Occurrence Count", "Original Examples", "Locations", "Parameter Examples"])

            # Add groups.
            for optimized in sorted(self.specs_opt_dictionary_groups.keys(), key=lambda x: x.lower()):
                group = self.specs_opt_dictionary_groups[optimized]
                ws.append([
                    optimized,
                    group["count"],
                    " | ".join(group["examples"]),
                    " | ".join(group["locations"]),
                    " | ".join(group["params"]),
                ])

            # Freeze header.
            ws.freeze_panes = "A2"
            # Enable filter.
            ws.auto_filter.ref = ws.dimensions
            # Format header.
            for cell in ws[1]:
                cell.font = Font(bold=True)
                cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
            # Format body.
            for row_cells in ws.iter_rows(min_row=2):
                for cell in row_cells:
                    cell.alignment = Alignment(vertical="top", wrap_text=True)

            # Adjust columns.
            for col_cells in ws.columns:
                col_letter = col_cells[0].column_letter
                max_len = len(str(col_cells[0].value or ""))
                for cell in col_cells[1:]:
                    value = "" if cell.value is None else str(cell.value)
                    max_len = max(max_len, min(len(value), 100))
                ws.column_dimensions[col_letter].width = max(18, min(max_len + 2, 80))

            # Save workbook.
            wb.save(target)
            # Inform user.
            messagebox.showinfo("Specs dictionary exported", f"Standard dictionary exported successfully:\n{target}")

        # Handle errors.
        except Exception as exc:
            messagebox.showerror("Specs dictionary export failed", f"Could not export standard dictionary.\n\nDetails:\n{type(exc).__name__}: {exc}")



    def _settings_file_path(self) -> Path:
        """Return the encrypted settings file path stored beside the script."""
        try:
            return Path(__file__).with_name("pruefturbo_settings.dat")
        except Exception:
            return Path.cwd() / "pruefturbo_settings.dat"

    def _settings_crypto_key(self) -> bytes:
        """Create a stable local key for lightweight settings encryption."""
        return hashlib.sha256(b"PruefTurbo::Tns2026::settings").digest()

    def _xor_crypt_settings_bytes(self, payload: bytes) -> bytes:
        """Encrypt/decrypt settings bytes using a repeated SHA-256 key stream."""
        key = self._settings_crypto_key()
        return bytes(byte ^ key[index % len(key)] for index, byte in enumerate(payload))

    def _load_encrypted_gui_settings(self) -> dict:
        """Load encrypted GUI settings, returning defaults if the file is missing or invalid."""
        settings_path = self._settings_file_path()
        try:
            if not settings_path.exists():
                return {}
            encrypted = base64.b64decode(settings_path.read_bytes())
            decoded = self._xor_crypt_settings_bytes(encrypted).decode("utf-8")
            loaded = json.loads(decoded)
            if isinstance(loaded, dict):
                return loaded
        except Exception:
            pass
        return {}

    def _protect_settings_file(self, protected: bool = True) -> None:
        """Hide/protect or unprotect the settings file."""
        settings_path = self._settings_file_path()
        try:
            if not settings_path.exists():
                return

            if os.name == "nt":
                FILE_ATTRIBUTE_HIDDEN = 0x02
                FILE_ATTRIBUTE_READONLY = 0x01
                FILE_ATTRIBUTE_SYSTEM = 0x04
                normal_attributes = 0x80

                if protected:
                    attrs = FILE_ATTRIBUTE_HIDDEN | FILE_ATTRIBUTE_READONLY | FILE_ATTRIBUTE_SYSTEM
                else:
                    attrs = normal_attributes

                ctypes.windll.kernel32.SetFileAttributesW(str(settings_path), attrs)
            else:
                current_mode = settings_path.stat().st_mode
                if protected:
                    settings_path.chmod(current_mode & ~stat.S_IWUSR & ~stat.S_IWGRP & ~stat.S_IWOTH)
                else:
                    settings_path.chmod(current_mode | stat.S_IWUSR)
        except Exception:
            pass

    def _save_encrypted_gui_settings(self) -> None:
        """Persist current GUI settings in an encrypted local settings file."""
        settings_path = self._settings_file_path()
        self._protect_settings_file(False)
        tab_visibility = {}
        for item in getattr(self, "gui_tab_registry", []):
            tab_visibility[item.get("key", "")] = bool(item.get("visible", False))
        payload = {
            "app": "PrüfTurbo",
            "version": 1,
            "tab_visibility": tab_visibility,
        }
        raw = json.dumps(payload, ensure_ascii=False, indent=2).encode("utf-8")
        encrypted = self._xor_crypt_settings_bytes(raw)
        settings_path.write_bytes(base64.b64encode(encrypted))
        self._protect_settings_file(True)

    def apply_persisted_gui_settings(self) -> None:
        """Apply saved encrypted tab settings, or keep defaults on first run/missing file."""
        saved = getattr(self, "saved_gui_settings", {}) or {}
        tab_visibility = saved.get("tab_visibility", {}) if isinstance(saved, dict) else {}
        if not isinstance(tab_visibility, dict) or not tab_visibility:
            return

        # Keep at least one normal tab visible even if the settings file is damaged.
        normal_visible_count = sum(
            1 for item in getattr(self, "gui_tab_registry", [])
            if item.get("key") != "hidden_replace" and tab_visibility.get(item.get("key"), item.get("visible", False))
        )
        if normal_visible_count <= 0:
            return

        desired_visibility = {}
        for item in getattr(self, "gui_tab_registry", []):
            key = item.get("key")
            desired_visibility[key] = bool(tab_visibility.get(key, item.get("visible", False)))

        self._rebuild_visible_notebook_tabs(desired_visibility)


    def toggle_hidden_replace_tab(self) -> None:
        """Show or hide the protected Hidden Replace tab after password validation."""
        password = simpledialog.askstring(
            "Password Required",
            "Enter password for Hidden Replace:",
            show="*",
            parent=self
        )
        if password != "Tns2026":
            if hasattr(self, "show_hidden_replace_var"):
                self.show_hidden_replace_var.set(False)
            messagebox.showerror("Access denied", "Wrong password. Hidden Replace remains unchanged.")
            return

        # Toggle visibility from the keyboard shortcut.
        if getattr(self, "hidden_replace_tab_visible", False):
            self.hide_hidden_replace_tab()
            return

        self.show_hidden_replace_var.set(True)
        if not self.hidden_replace_tab_visible:
            self._show_notebook_tab(self.hidden_replace_tab, "Hidden Replace")
            self.hidden_replace_tab_visible = True
        self._set_tab_registry_visibility(self.hidden_replace_tab, True)
        self.notebook.select(self.hidden_replace_tab)
        self.status_var.set("Hidden Replace tab shown.")

    def hide_hidden_replace_tab(self) -> None:
        # Hide tab again.
        if getattr(self, "hidden_replace_tab_visible", False):
            self._hide_notebook_tab(self.hidden_replace_tab)
            self.hidden_replace_tab_visible = False
        if hasattr(self, "show_hidden_replace_var"):
            self.show_hidden_replace_var.set(False)
        self._set_tab_registry_visibility(self.hidden_replace_tab, False)
        try:
            if self._is_notebook_tab_visible(self.main_tab):
                self.notebook.select(self.main_tab)
        except Exception:
            pass
        self.status_var.set("Hidden Replace tab hidden.")

    def on_ctrl_r_hidden_replace(self, event=None):
        """Keyboard shortcut handler for protected Hidden Replace tab."""
        self.toggle_hidden_replace_tab()
        return "break"

    def on_ctrl_zero_tab_settings(self, event=None):
        """Keyboard shortcut handler for protected GUI tab settings."""
        self.show_tab_settings_dialog()
        return "break"

    def _is_notebook_tab_visible(self, tab_frame) -> bool:
        """Return True only when a notebook tab is actually shown to the user."""
        try:
            tab_id = str(tab_frame)
            if tab_id not in self.notebook.tabs():
                return False
            return str(self.notebook.tab(tab_frame, "state")) != "hidden"
        except Exception:
            return False

    def _show_notebook_tab(self, tab_frame, title: str) -> None:
        """Show an existing notebook tab immediately, even if it was hidden before."""
        try:
            # ttk.Notebook.add() on an already-managed hidden tab makes it visible again.
            # This is more reliable than only changing the state, especially after hide().
            self.notebook.add(tab_frame, text=title)
        except Exception:
            pass

        try:
            self.notebook.tab(tab_frame, text=title, state="normal")
        except Exception:
            pass

        self._set_tab_registry_visibility(tab_frame, True)

    def _hide_notebook_tab(self, tab_frame) -> None:
        """Hide a notebook tab immediately while preserving its content."""
        try:
            self.notebook.hide(tab_frame)
        except Exception:
            try:
                self.notebook.tab(tab_frame, state="hidden")
            except Exception:
                pass

        self._set_tab_registry_visibility(tab_frame, False)

    def _first_visible_notebook_tab(self):
        """Return the first currently visible notebook tab id, ignoring hidden tabs."""
        try:
            for tab_id in self.notebook.tabs():
                try:
                    if str(self.notebook.tab(tab_id, "state")) != "hidden":
                        return tab_id
                except Exception:
                    continue
        except Exception:
            pass
        return None

    def _set_tab_registry_visibility(self, tab_frame, visible: bool) -> None:
        """Keep the tab registry in sync with Notebook visibility."""
        try:
            for item in getattr(self, "gui_tab_registry", []):
                if item.get("frame") is tab_frame:
                    item["visible"] = bool(visible)
                    break
        except Exception:
            pass


    def _rebuild_visible_notebook_tabs(self, desired_visibility: dict, selected_frame=None) -> None:
        """Rebuild visible notebook tabs in registry order so activation/deactivation reflects immediately."""
        registry = list(getattr(self, "gui_tab_registry", []))

        # Remove all currently managed tabs first. The frame widgets are not destroyed.
        for tab_id in list(self.notebook.tabs()):
            try:
                self.notebook.forget(tab_id)
            except Exception:
                pass

        first_visible_frame = None
        selected_still_visible = False

        for item in registry:
            key = item.get("key")
            frame = item.get("frame")
            title = item.get("text", "")
            visible = bool(desired_visibility.get(key, False))
            item["visible"] = visible

            if key == "hidden_replace":
                self.hidden_replace_tab_visible = visible
                if hasattr(self, "show_hidden_replace_var"):
                    self.show_hidden_replace_var.set(visible)

            if not visible:
                continue

            try:
                self.notebook.add(frame, text=title, state="normal")
                if first_visible_frame is None:
                    first_visible_frame = frame
                if selected_frame is frame:
                    selected_still_visible = True
            except Exception:
                pass

        # Keep the current tab selected when it is still visible; otherwise select the first visible tab.
        try:
            if selected_still_visible and selected_frame is not None:
                self.notebook.select(selected_frame)
            elif first_visible_frame is not None:
                self.notebook.select(first_visible_frame)
        except Exception:
            pass

        try:
            self.notebook.update_idletasks()
            self.update_idletasks()
        except Exception:
            pass

    def show_tab_settings_dialog(self) -> None:
        """Password-protected settings dialog to activate/deactivate GUI tabs individually."""
        password = simpledialog.askstring(
            "Password Required",
            "Enter password for GUI tab settings:",
            show="*",
            parent=self
        )
        if password != "Tns2026":
            messagebox.showerror("Access denied", "Wrong password. Settings remain closed.")
            return

        dialog = tk.Toplevel(self)
        apply_pruefturbo_window_icon(dialog)
        dialog.title("GUI Tab Settings")
        dialog.transient(self)
        dialog.grab_set()

        ttk.Label(
            dialog,
            text="Activate / deactivate tabs individually:",
            anchor=tk.W
        ).pack(fill=tk.X, padx=12, pady=(12, 6))

        vars_by_key = {}
        body = ttk.Frame(dialog)
        body.pack(fill=tk.BOTH, expand=True, padx=12, pady=(0, 8))

        # Refresh registry states from current notebook state.
        for item in getattr(self, "gui_tab_registry", []):
            item["visible"] = self._is_notebook_tab_visible(item["frame"])

        for row, item in enumerate(getattr(self, "gui_tab_registry", [])):
            key = item["key"]
            tab_text = item["text"]
            var = tk.BooleanVar(value=bool(item.get("visible", False)))
            vars_by_key[key] = var
            ttk.Checkbutton(body, text=tab_text, variable=var).grid(row=row, column=0, sticky=tk.W, pady=4)

        note = ttk.Label(
            dialog,
            text="At least one normal tab must remain active. Hidden Replace can also be controlled with Ctrl+R.",
            wraplength=420,
            foreground="#555555"
        )
        note.pack(fill=tk.X, padx=12, pady=(0, 8))

        protection_var = tk.BooleanVar(value=True)

        protection_frame = ttk.LabelFrame(dialog, text="Settings File Protection")
        protection_frame.pack(fill=tk.X, padx=12, pady=(0, 10))

        ttk.Checkbutton(
            protection_frame,
            text="Hide and protect pruefturbo_settings.dat",
            variable=protection_var
        ).pack(anchor=tk.W, padx=10, pady=8)

        def apply_tab_settings(close_after=False):
            registry = list(getattr(self, "gui_tab_registry", []))
            normal_visible_count = sum(
                1 for item in registry
                if item["key"] != "hidden_replace" and vars_by_key[item["key"]].get()
            )
            if normal_visible_count <= 0:
                messagebox.showerror("Invalid tab settings", "At least one normal tab must remain active.", parent=dialog)
                return

            selected_frame = None
            try:
                selected_frame = self.nametowidget(self.notebook.select())
            except Exception:
                selected_frame = None

            desired_visibility = {
                item["key"]: bool(vars_by_key[item["key"]].get())
                for item in registry
            }

            # Rebuild the Notebook immediately in registry order. This is more reliable than
            # hiding/showing individual ttk.Notebook tabs, because hidden tabs can otherwise
            # stay visually stale until the whole GUI is restarted on some Tk versions.
            self._rebuild_visible_notebook_tabs(desired_visibility, selected_frame=selected_frame)

            # Refresh checkboxes from the live Notebook state after rebuilding.
            try:
                for item in registry:
                    vars_by_key[item["key"]].set(self._is_notebook_tab_visible(item["frame"]))
            except Exception:
                pass

            # Persist settings to the encrypted local settings file for the next run.
            try:
                self._save_encrypted_gui_settings()
                if not protection_var.get():
                    self._protect_settings_file(False)
                self.saved_gui_settings = self._load_encrypted_gui_settings()
            except Exception as save_exc:
                messagebox.showwarning(
                    "Settings not saved",
                    f"Tab settings were applied, but the encrypted settings file could not be saved.\n\nDetails: {type(save_exc).__name__}: {save_exc}",
                    parent=dialog
                )

            self.status_var.set("GUI tab settings saved and applied.")
            if close_after:
                dialog.destroy()

        buttons = ttk.Frame(dialog)
        buttons.pack(fill=tk.X, padx=12, pady=(0, 12))
        ttk.Button(buttons, text="Save Setting", command=lambda: apply_tab_settings(False)).pack(side=tk.LEFT, padx=(0, 8))
        ttk.Button(buttons, text="Finish", command=lambda: apply_tab_settings(True)).pack(side=tk.LEFT, padx=(0, 8))
        ttk.Button(buttons, text="Cancel", command=dialog.destroy).pack(side=tk.RIGHT)

        # Fit the settings window to its current contents instead of using a fixed geometry.
        dialog.update_idletasks()
        req_width = max(dialog.winfo_reqwidth(), 460)
        req_height = dialog.winfo_reqheight()
        parent_x = self.winfo_rootx()
        parent_y = self.winfo_rooty()
        parent_w = max(self.winfo_width(), 1)
        parent_h = max(self.winfo_height(), 1)
        x = parent_x + max(0, (parent_w - req_width) // 2)
        y = parent_y + max(0, (parent_h - req_height) // 2)
        dialog.geometry(f"{req_width}x{req_height}+{x}+{y}")
        dialog.minsize(req_width, req_height)
        dialog.resizable(False, False)

