    def browse_hidden_specs_file(self) -> None:
        selected = filedialog.askopenfilename(title="Select specs Excel workbook", filetypes=[("Excel workbooks", "*.xlsx *.xlsm"), ("All files", "*.*")])
        if selected:
            self.hidden_specs_file_var.set(selected)
            self.load_hidden_specs_sheets()

    def browse_hidden_replace_file(self) -> None:
        selected = filedialog.askopenfilename(title="Select replace dictionary Excel workbook", filetypes=[("Excel workbooks", "*.xlsx *.xlsm"), ("All files", "*.*")])
        if selected:
            self.hidden_replace_file_var.set(selected)
            self.load_hidden_replace_sheets()

    def load_hidden_specs_sheets(self) -> None:
        self._load_sheet_names_to_combo(self.hidden_specs_file_var.get(), self.hidden_specs_sheet_combo, self.hidden_specs_sheet_var)

    def load_hidden_replace_sheets(self) -> None:
        self._load_sheet_names_to_combo(self.hidden_replace_file_var.get(), self.hidden_replace_sheet_combo, self.hidden_replace_sheet_var)

    def _load_sheet_names_to_combo(self, path_value, combo, var) -> None:
        try:
            if not path_value:
                return
            from openpyxl import load_workbook
            wb = load_workbook(path_value, read_only=True, data_only=False)
            sheets = wb.sheetnames
            wb.close()
            combo["values"] = sheets
            if sheets:
                var.set(sheets[0])
        except Exception as exc:
            messagebox.showerror("Load sheets failed", f"Could not load sheets.\n\nDetails:\n{type(exc).__name__}: {exc}")

    def _resolve_hidden_column_index(self, ws, column_ref):
        from openpyxl.utils.cell import column_index_from_string
        value = str(column_ref or "").strip()
        if not value:
            raise ValueError("Column reference cannot be empty.")
        if re.fullmatch(r"[A-Za-z]+", value):
            return column_index_from_string(value.upper())
        for cell in ws[1]:
            if str(cell.value or "").strip().lower() == value.lower():
                return cell.column
        raise ValueError(f"Could not resolve column: {value}. Use Excel letter or exact header name.")

    def build_hidden_replace_map(self, ws_replace):
        find_col = self._resolve_hidden_column_index(ws_replace, self.hidden_search_column_var.get())
        repl_col = self._resolve_hidden_column_index(ws_replace, self.hidden_replace_column_var.get())
        replace_map = {}
        for row in range(2, ws_replace.max_row + 1):
            find_value = ws_replace.cell(row=row, column=find_col).value
            repl_value = ws_replace.cell(row=row, column=repl_col).value
            if find_value is None or repl_value is None:
                continue
            find_text = str(find_value).strip()
            repl_text = str(repl_value).strip()
            if find_text:
                replace_map[find_text] = repl_text
        return replace_map

    def get_hidden_target_columns(self):
        raw = self.hidden_target_columns_var.get().strip()
        if not raw:
            raise ValueError("Please enter target columns, e.g. I,J,K,L,M")
        return [part.strip().upper() for part in re.split(r"[,;]+", raw) if part.strip()]

    def collect_hidden_replacements(self):
        from openpyxl import load_workbook
        specs_path = self.hidden_specs_file_var.get().strip()
        replace_path = self.hidden_replace_file_var.get().strip()
        specs_sheet = self.hidden_specs_sheet_var.get().strip()
        replace_sheet = self.hidden_replace_sheet_var.get().strip()
        if not specs_path or not replace_path:
            raise ValueError("Please select both Specs Excel and Replace Excel files.")
        if not specs_sheet or not replace_sheet:
            raise ValueError("Please select both Specs and Replace sheets.")

        wb_specs = load_workbook(specs_path)
        ws_specs = wb_specs[specs_sheet]
        wb_replace = load_workbook(replace_path, data_only=True)
        ws_replace = wb_replace[replace_sheet]
        replace_map = self.build_hidden_replace_map(ws_replace)
        target_cols = self.get_hidden_target_columns()
        preview_rows = []

        for col_letter in target_cols:
            for cell in ws_specs[col_letter]:
                if cell.row == 1 or cell.value is None:
                    continue
                original_text = str(cell.value)
                new_text = original_text
                matched_items = []
                for find_text in sorted(replace_map.keys(), key=len, reverse=True):
                    if find_text in new_text:
                        new_text = new_text.replace(find_text, replace_map[find_text])
                        matched_items.append((find_text, replace_map[find_text]))
                if new_text != original_text:
                    preview_rows.append({"cell": cell.coordinate, "original": original_text, "new": new_text, "matches": matched_items})

        wb_replace.close()
        return wb_specs, preview_rows

    def preview_hidden_replacements(self) -> None:
        try:
            for item in self.hidden_replace_tree.get_children(""):
                self.hidden_replace_tree.delete(item)
            wb_specs, preview_rows = self.collect_hidden_replacements()
            wb_specs.close()
            self.hidden_replace_preview_rows = preview_rows
            for row in preview_rows:
                first_match = row["matches"][0] if row["matches"] else ("", "")
                root = self.hidden_replace_tree.insert("", tk.END, text=row["original"], values=(row["cell"], first_match[0], first_match[1]), open=False)
                self.hidden_replace_tree.insert(root, tk.END, text="New text", values=(row["cell"], "", row["new"]), open=False)
            self.hidden_replace_stats_var.set(f"Preview completed | Changed cells: {len(preview_rows)}")
            if not preview_rows:
                messagebox.showinfo("Hidden Replace", "No matching items found.")
        except Exception as exc:
            messagebox.showerror("Preview failed", f"Could not preview replacements.\n\nDetails:\n{type(exc).__name__}: {exc}")

    def apply_hidden_replacements_save_copy(self) -> None:
        try:
            from datetime import datetime
            wb_specs, preview_rows = self.collect_hidden_replacements()
            if not preview_rows:
                wb_specs.close()
                messagebox.showinfo("Hidden Replace", "No matching items found. Nothing was saved.")
                return
            ws_specs = wb_specs[self.hidden_specs_sheet_var.get().strip()]
            for row in preview_rows:
                ws_specs[row["cell"]].value = row["new"]

            source_path = Path(self.hidden_specs_file_var.get().strip())
            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            default_name = f"{source_path.stem}_HiddenReplace_{timestamp}{source_path.suffix}"
            target = filedialog.asksaveasfilename(
                title="Save new specs workbook",
                defaultextension=source_path.suffix or ".xlsx",
                initialfile=default_name,
                filetypes=[("Excel workbooks", "*.xlsx *.xlsm"), ("All files", "*.*")]
            )
            if not target:
                wb_specs.close()
                self.hidden_replace_stats_var.set("Save cancelled.")
                return
            wb_specs.save(target)
            wb_specs.close()
            self.hidden_replace_stats_var.set(f"Saved new specs file: {target}")
            self.status_var.set(f"Hidden replacement saved: {target}")
            messagebox.showinfo("Hidden Replace completed", f"New specs file saved successfully.\n\nChanged cells: {len(preview_rows)}\n\n{target}")
            self.hide_hidden_replace_tab()
        except Exception as exc:
            messagebox.showerror("Apply failed", f"Could not apply replacements.\n\nDetails:\n{type(exc).__name__}: {exc}")



    # This decorator marks the next method as independent from object instance data.
    @staticmethod
    def _attach_scrollbars(parent: ttk.Frame, tree: ttk.Treeview, row_offset: int = 0) -> None:
        yscroll = ttk.Scrollbar(parent, orient=tk.VERTICAL, command=tree.yview)
        xscroll = ttk.Scrollbar(parent, orient=tk.HORIZONTAL, command=tree.xview)
        tree.configure(yscrollcommand=yscroll.set, xscrollcommand=xscroll.set)
        tree.grid(row=row_offset, column=0, sticky=tk.NSEW)
        yscroll.grid(row=row_offset, column=1, sticky=tk.NS)
        xscroll.grid(row=row_offset + 1, column=0, sticky=tk.EW)
        parent.rowconfigure(row_offset, weight=1)
        parent.columnconfigure(0, weight=1)

